int main(void) {
    /* Allocate a raw byte buffer */
    uint8_t *buffer = (uint8_t *)malloc(16);
    if (buffer == NULL) {
        return 1;
    }

    /* Store values using byte operations only */
    /* A byte op stores the low 8 bits of the value at that byte offset */
    buffer[0] = (uint8_t)(100 & 0xFF);
    buffer[4] = (uint8_t)(200 & 0xFF);
    buffer[8] = (uint8_t)(250 & 0xFF);

    /* Read all three back with byte operations */
    uint8_t val0 = buffer[0];
    uint8_t val4 = buffer[4];
    uint8_t val8 = buffer[8];

    /* Print them on one line separated by single spaces, then a newline */
    printf("%u %u %u\n", (unsigned int)val0, (unsigned int)val4, (unsigned int)val8);

    free(buffer);
    return 0;
}

