#include <stdio.h>
#include <string.h>
#include <stdlib.h>

/* Simple hash map implementation */
#define MAP_SIZE 1024

typedef struct {
    char *key;
    int value;
    int used;
} MapEntry;

typedef struct {
    MapEntry entries[MAP_SIZE];
} Map;

static unsigned int hash(const char *key) {
    unsigned int h = 0;
    while (*key) {
        h = h * 31 + (unsigned char)*key;
        key++;
    }
    return h % MAP_SIZE;
}

void map_init(Map *m) {
    memset(m->entries, 0, sizeof(m->entries));
}

void map_insert(Map *m, const char *key, int value) {
    unsigned int idx = hash(key);
    MapEntry *e = &m->entries[idx];
    if (!e->used || strcmp(e->key, key) == 0) {
        e->key = strdup(key);
        e->value = value;
        e->used = 1;
    }
}

int map_lookup(Map *m, const char *key, int *out_value) {
    unsigned int idx = hash(key);
    MapEntry *e = &m->entries[idx];
    if (e->used && strcmp(e->key, key) == 0) {
        *out_value = e->value;
        return 1;
    }
    return 0;
}

void map_destroy(Map *m) {
    for (int i = 0; i < MAP_SIZE; i++) {
        if (m->entries[i].used) {
            free(m->entries[i].key);
        }
    }
}

int main(void) {
    Map map;
    map_init(&map);

    map_insert(&map, "a", 10);
    map_insert(&map, "b", 20);
    map_insert(&map, "c", 30);
    map_insert(&map, "d", 40);
    map_insert(&map, "e", 50);

    const char *keys[] = {"a", "b", "c", "d", "e"};
    for (int i = 0; i < 5; i++) {
        int value;
        if (map_lookup(&map, keys[i], &value)) {
            printf("%d\n", value);
        }
    }

    map_destroy(&map);
    return 0;
}

