/* Simple hash map implementation */
#define MAP_BUCKETS 64

typedef struct {
    char *key;
    int value;
    struct map_entry *next;
} map_entry;

typedef struct {
    map_entry **buckets;
    int num_buckets;
} map;

static unsigned int hash(const char *key) {
    unsigned int h = 0;
    const char *p = key;
    while (*p) {
        h = h * 31 + (unsigned char)*p++;
    }
    return h % 64;
}

static void map_init(map *m) {
    m->num_buckets = MAP_BUCKETS;
    m->buckets = (map_entry **)calloc(m->num_buckets, sizeof(map_entry *));
}

static void map_free(map *m) {
    for (int i = 0; i < m->num_buckets; i++) {
        map_entry *e = m->buckets[i];
        while (e) {
            map_entry *next = e->next;
            free(e->key);
            free(e);
            e = next;
        }
    }
    free(m->buckets);
}

static void map_insert(map *m, const char *key, int value) {
    unsigned int idx = hash(key);
    map_entry *e = m->buckets[idx];
    while (e) {
        if (strcmp(e->key, key) == 0) {
            e->value = value;
            return;
        }
        e = e->next;
    }
    e = (map_entry *)malloc(sizeof(map_entry));
    e->key = strdup(key);
    e->value = value;
    e->next = m->buckets[idx];
    m->buckets[idx] = e;
}

static int map_lookup(map *m, const char *key, int *value) {
    unsigned int idx = hash(key);
    map_entry *e = m->buckets[idx];
    while (e) {
        if (strcmp(e->key, key) == 0) {
            *value = e->value;
            return 1;
        }
        e = e->next;
    }
    return 0;
}

