/*
 * Simple hash map implementation for key->int pairs.
 */

typedef struct MapEntry {
    char *key;
    int value;
    struct MapEntry *next;
} MapEntry;

typedef struct Map {
    MapEntry **buckets;
    int num_buckets;
    int size;
} Map;

/* Hash function */
unsigned int hash_string(const char *str, int num_buckets) {
    unsigned int hash = 0;
    unsigned int c;
    while ((c = *str++)) {
        hash = ((hash << 5) - hash) + c;
        hash = (hash + (hash << 1)) + (hash << 4) + (hash << 7) + (hash << 8);
    }
    return hash % num_buckets;
}

/* Create a new map */
Map *map_create(int num_buckets) {
    Map *map = (Map *)malloc(sizeof(Map));
    if (!map) return NULL;
    map->num_buckets = num_buckets;
    map->size = 0;
    map->buckets = (MapEntry **)calloc(num_buckets, sizeof(MapEntry *));
    if (!map->buckets) {
        free(map);
        return NULL;
    }
    return map;
}

/* Free a map */
void map_destroy(Map *map) {
    if (!map) return;
    for (int i = 0; i < map->num_buckets; i++) {
        MapEntry *entry = map->buckets[i];
        while (entry) {
            MapEntry *next = entry->next;
            free(entry->key);
            free(entry);
            entry = next;
        }
    }
    free(map->buckets);
    free(map);
}

/* Insert a key-value pair into the map */
void map_insert(Map *map, const char *key, int value) {
    unsigned int idx = hash_string(key, map->num_buckets);
    MapEntry *entry = map->buckets[idx];

    /* Check if key already exists */
    while (entry) {
        if (strcmp(entry->key, key) == 0) {
            entry->value = value;
            return;
        }
        entry = entry->next;
    }

    /* Create new entry */
    entry = (MapEntry *)malloc(sizeof(MapEntry));
    if (!entry) return;
    entry->key = (char *)malloc(strlen(key) + 1);
    if (!entry->key) {
        free(entry);
        return;
    }
    strcpy(entry->key, key);
    entry->value = value;
    entry->next = map->buckets[idx];
    map->buckets[idx] = entry;
    map->size++;
}

/* Look up a key in the map, returns 1 if found and stores value in *out, 0 otherwise */
int map_lookup(Map *map, const char *key, int *out) {
    unsigned int idx = hash_string(key, map->num_buckets);
    MapEntry *entry = map->buckets[idx];
    while (entry) {
        if (strcmp(entry->key, key) == 0) {
            *out = entry->value;
            return 1;
        }
        entry = entry->next;
    }
    return 0;
}

