    for (int i = 0; i < map->capacity; i++) {
        if (map->entries[i].key == NULL) {
            map->entries[i].key = strdup(key);
            map->entries[i].value = value;
            map->size++;
            return 0;
        }
        if (strcmp(map->entries[i].key, key) == 0) {
