    int start = idx;
    while (map->entries[idx].used) {
        if (strcmp(map->entries[idx].key, key) == 0) {
            map->entries[idx].value = value;
            return 0; // update existing
        }
        idx = (idx + 1) % MAP_SIZE;
    }
    strcpy(map->entries[idx].key, key);
    map->entries[idx].value = value;
    map->entries[idx].used = 1;
    map->size++;
    return 1;
}

int map_contains(Map *map, const char *key) {
    unsigned int idx = hash_key(key);
    int start = idx;
    while (map->entries[idx].used) {
        if (strcmp(map->entries[idx].key, key) == 0) {
            return 1;
        }
        idx = (idx + 1) % MAP_SIZE;
        if (idx == start) break;
    }
    return 0;
}

