/* Simple hash map implementation */
#define MAP_SIZE 64
#define INITIAL_SIZE 16

typedef struct {
    char *key;
    int value;
    int occupied;
} MapEntry;

typedef struct {
    MapEntry *entries;
    int size;
    int count;
} Map;

static unsigned int hash_string(const char *str) {
    unsigned int hash = 5381;
    while (*str) {
        hash = ((hash << 5) + hash) + (unsigned char)*str++;
        hash = hash & 0xFFFFFFFF;
    }
    return hash;
}

static Map *map_create(int initial_size) {
    Map *m = (Map *)malloc(sizeof(Map));
    if (!m) return NULL;
    m->size = initial_size;
    m->count = 0;
    m->entries = (MapEntry *)calloc(initial_size, sizeof(MapEntry));
    if (!m->entries) {
        free(m);
        return NULL;
    }
    return m;
}

static void map_free(Map *m) {
    if (!m) return;
    for (int i = 0; i < m->size; i++) {
        if (m->entries[i].occupied) {
            free(m->entries[i].key);
        }
    }
    free(m->entries);
    free(m);
}

static void map_insert(Map *m, const char *key, int value) {
    unsigned int hash = hash_string(key);
    int index = hash % m->size;

    // Linear probing
    while (m->entries[index].occupied) {
        if (strcmp(m->entries[index].key, key) == 0) {
            m->entries[index].value = value;
            return;
        }
        index = (index + 1) % m->size;
    }

    m->entries[index].key = strdup(key);
    m->entries[index].value = value;
    m->entries[index].occupied = 1;
    m->count++;
}

static int map_contains(Map *m, const char *key) {
    if (!m) return 0;
    unsigned int hash = hash_string(key);
    int index = hash % m->size;

    int start = index;
    while (m->entries[index].occupied) {
        if (strcmp(m->entries[index].key, key) == 0) {
            return 1;
        }
        index = (index + 1) % m->size;
        if (index == start) break;
    }
    return 0;
}

