/* Minimal JSON library implementation */

typedef enum {
    JSON_NULL,
    JSON_BOOL,
    JSON_NUMBER,
    JSON_STRING,
    JSON_ARRAY,
    JSON_OBJECT
} json_type;

typedef struct json_value json_value;

struct json_value {
    json_type type;
    union {
        int boolean;
        double number;
        char *string;
        struct {
            json_value **items;
            size_t length;
            size_t capacity;
        } array;
        struct {
            struct {
                char *key;
                json_value *value;
            } *members;
            size_t length;
            size_t capacity;
        } object;
    } u;
};

static json_value *json_new(json_type type) {
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    v->type = type;
    return v;
}

static void json_free(json_value *v) {
    if (!v) return;
    switch (v->type) {
        case JSON_STRING:
            free(v->u.string);
            break;
        case JSON_ARRAY:
            for (size_t i = 0; i < v->u.array.length; i++) {
                json_free(v->u.array.items[i]);
            }
            free(v->u.array.items);
            break;
        case JSON_OBJECT:
            for (size_t i = 0; i < v->u.object.length; i++) {
                free(v->u.object.members[i].key);
                json_free(v->u.object.members[i].value);
            }
            free(v->u.object.members);
            break;
        default:
            break;
    }
    free(v);
}

static json_value *json_string(const char *s) {
    json_value *v = json_new(JSON_STRING);
    v->u.string = strdup(s);
    return v;
}

static json_value *json_number(double d) {
    json_value *v = json_new(JSON_NUMBER);
    v->u.number = d;
    return v;
}

static json_value *json_array_new(size_t capacity) {
    json_value *v = json_new(JSON_ARRAY);
    v->u.array.capacity = capacity;
    v->u.array.length = 0;
    v->u.array.items = (json_value **)calloc(capacity, sizeof(json_value *));
    return v;
}

static void json_array_append(json_value *arr, json_value *item) {
    if (arr->u.array.length >= arr->u.array.capacity) {
        arr->u.array.capacity *= 2;
        arr->u.array.items = (json_value **)realloc(arr->u.array.items, arr->u.array.capacity * sizeof(json_value *));
    }
    arr->u.array.items[arr->u.array.length++] = item;
}

static json_value *json_object_new(size_t capacity) {
    json_value *v = json_new(JSON_OBJECT);
    v->u.object.capacity = capacity;
    v->u.object.length = 0;
    v->u.object.members = (struct { char *key; json_value *value; } *)calloc(capacity, sizeof(struct { char *key; json_value *value; }));
    return v;
}

static void json_object_set(json_value *obj, const char *key, json_value *value) {
    if (obj->u.object.length >= obj->u.object.capacity) {
        obj->u.object.capacity *= 2;
        obj->u.object.members = (struct { char *key; json_value *value; } *)realloc(obj->u.object.members, obj->u.object.capacity * sizeof(struct { char *key; json_value *value; }));
    }
    obj->u.object.members[obj->u.object.length].key = strdup(key);
    obj->u.object.members[obj->u.object.length].value = value;
    obj->u.object.length++;
}

static json_value *json_object_get(json_value *obj, const char *key) {
    for (size_t i = 0; i < obj->u.object.length; i++) {
        if (strcmp(obj->u.object.members[i].key, key) == 0) {
            return obj->u.object.members[i].value;
        }
    }
    return NULL;
}

/* Stringify JSON */
static void json_stringify_rec(json_value *v, char **buf, size_t *len, size_t *cap) {
    #define GROW(n) do { \
        while (*cap - *len < (n)) { \
            *cap *= 2; \
            *buf = (char *)realloc(*buf, *cap); \
        } \
    } while(0)

    switch (v->type) {
        case JSON_NULL:
            GROW(5);
            strcpy(*buf + *len, "null");
            *len += 4;
            break;
        case JSON_BOOL:
            GROW(5);
            if (v->u.boolean) {
                strcpy(*buf + *len, "true");
                *len += 4;
            } else {
                strcpy(*buf + *len, "false");
                *len += 5;
            }
            break;
        case JSON_NUMBER: {
            char tmp[32];
            /* Check if it's an integer */
            if (v->u.number == (int)v->u.number) {
                snprintf(tmp, sizeof(tmp), "%d", (int)v->u.number);
            } else {
                snprintf(tmp, sizeof(tmp), "%g", v->u.number);
            }
            size_t tlen = strlen(tmp);
            GROW(tlen + 1);
            strcpy(*buf + *len, tmp);
            *len += tlen;
            break;
        }
        case JSON_STRING: {
            GROW(2);
            *buf[(*len)++] = '"';
            for (const char *p = v->u.string; *p; p++) {
                if (*p == '"' || *p == '\\') {
                    GROW(2);
                    *buf[(*len)++] = '\\';
                    *buf[(*len)++] = *p;
                } else if (*p == '\n') {
                    GROW(3);
                    *buf[(*len)++] = '\\';
                    *buf[(*len)++] = 'n';
                } else if (*p == '\r') {
                    GROW(3);
                    *buf[(*len)++] = '\\';
                    *buf[(*len)++] = 'r';
                } else if (*p == '\t') {
                    GROW(3);
                    *buf[(*len)++] = '\\';
                    *buf[(*len)++] = 't';
                } else {
                    GROW(1);
                    *buf[(*len)++] = *p;
                }
            }
            GROW(1);
            *buf[(*len)++] = '"';
            break;
        }
        case JSON_ARRAY: {
            GROW(2);
            *buf[(*len)++] = '[';
            for (size_t i = 0; i < v->u.array.length; i++) {
                if (i > 0) {
                    GROW(1);
                    *buf[(*len)++] = ',';
                }
                json_stringify_rec(v->u.array.items[i], buf, len, cap);
            }
            GROW(1);
            *buf[(*len)++] = ']';
            break;
        }
        case JSON_OBJECT: {
            GROW(2);
            *buf[(*len)++] = '{';
            for (size_t i = 0; i < v->u.object.length; i++) {
                if (i > 0) {
                    GROW(1);
                    *buf[(*len)++] = ',';
                }
                /* key */
                GROW(2);
                *buf[(*len)++] = '"';
                for (const char *p = v->u.object.members[i].key; *p; p++) {
                    if (*p == '"' || *p == '\\') {
                        GROW(2);
                        *buf[(*len)++] = '\\';
                        *buf[(*len)++] = *p;
                    } else {
                        GROW(1);
                        *buf[(*len)++] = *p;
                    }
                }
                GROW(1);
                *buf[(*len)++] = '"';
                GROW(1);
                *buf[(*len)++] = ':';
                json_stringify_rec(v->u.object.members[i].value, buf, len, cap);
            }
            GROW(1);
            *buf[(*len)++] = '}';
            break;
        }
    }
    GROW(1);
    *buf[*len] = '\0';
    #undef GROW
}

static char *json_stringify(json_value *v) {
    size_t cap = 256;
    size_t len = 0;
    char *buf = (char *)malloc(cap);
    buf[0] = '\0';
    json_stringify_rec(v, &buf, &len, &cap);
    return buf;
}

/* Parse JSON */
static const char *skip_whitespace(const char *p) {
    while (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r') p++;
    return p;
}

static json_value *json_parse_rec(const char **pp) {
    const char *p = skip_whitespace(*pp);

    if (*p == 'n') {
        if (strncmp(p, "null", 4) == 0) {
            *pp = p + 4;
            return json_new(JSON_NULL);
        }
        return NULL;
    }
    if (*p == 't') {
        if (strncmp(p, "true", 4) == 0) {
            *pp = p + 4;
            json_value *v = json_new(JSON_BOOL);
            v->u.boolean = 1;
            return v;
        }
        return NULL;
    }
    if (*p == 'f') {
        if (strncmp(p, "false", 5) == 0) {
            *pp = p + 5;
            json_value *v = json_new(JSON_BOOL);
            v->u.boolean = 0;
            return v;
        }
        return NULL;
    }
    if (*p == '"') {
        p++;
        char *str = (char *)malloc(1024);
        size_t slen = 0;
        while (*p && *p != '"') {
            if (*p == '\\') {
                p++;
                switch (*p) {
                    case '"': str[slen++] = '"'; break;
                    case '\\': str[slen++] = '\\'; break;
                    case 'n': str[slen++] = '\n'; break;
                    case 'r': str[slen++] = '\r'; break;
                    case 't': str[slen++] = '\t'; break;
                    default: str[slen++] = *p; break;
                }
            } else {
                str[slen++] = *p;
            }
            p++;
        }
        if (*p == '"') p++;
        str[slen] = '\0';
        *pp = p;
        json_value *v = json_new(JSON_STRING);
        v->u.string = str;
        return v;
    }
    if (*p == '[') {
        p++;
        json_value *arr = json_array_new(8);
        p = skip_whitespace(p);
        if (*p == ']') {
            *pp = p + 1;
            return arr;
        }
        while (1) {
            json_value *item = json_parse_rec(&p);
            if (!item) {
                json_free(arr);
                return NULL;
            }
            json_array_append(arr, item);
            p = skip_whitespace(p);
            if (*p == ',') {
                p++;
                p = skip_whitespace(p);
            } else if (*p == ']') {
                *pp = p + 1;
                return arr;
            } else {
                json_free(arr);
                return NULL;
            }
        }
    }
    if (*p == '{') {
        p++;
        json_value *obj = json_object_new(8);
        p = skip_whitespace(p);
        if (*p == '}') {
            *pp = p + 1;
            return obj;
        }
        while (1) {
            p = skip_whitespace(p);
            if (*p != '"') {
                json_free(obj);
                return NULL;
            }
            p++;
            char *key = (char *)malloc(1024);
            size_t klen = 0;
            while (*p && *p != '"') {
                if (*p == '\\') {
                    p++;
                    switch (*p) {
                        case '"': key[klen++] = '"'; break;
                        case '\\': key[klen++] = '\\'; break;
                        case 'n': key[klen++] = '\n'; break;
                        case 'r': key[klen++] = '\r'; break;
                        case 't': key[klen++] = '\t'; break;
                        default: key[klen++] = *p; break;
                    }
                } else {
                    key[klen++] = *p;
                }
                p++;
            }
            if (*p == '"') p++;
            key[klen] = '\0';

            p = skip_whitespace(p);
            if (*p != ':') {
                free(key);
                json_free(obj);
                return NULL;
            }
            p++;

            json_value *val = json_parse_rec(&p);
            if (!val) {
                free(key);
                json_free(obj);
                return NULL;
            }

            json_object_set(obj, key, val);
            free(key);

            p = skip_whitespace(p);
            if (*p == ',') {
                p++;
            } else if (*p == '}') {
                *pp = p + 1;
                return obj;
            } else {
                json_free(obj);
                return NULL;
            }
        }
    }
    /* Number */
    char *end;
    double num = strtod(p, &end);
    if (end == p) return NULL;
    *pp = end;
    json_value *v = json_new(JSON_NUMBER);
    v->u.number = num;
    return v;
}

static json_value *json_parse(const char *str) {
    const char *p = str;
    json_value *v = json_parse_rec(&p);
    return v;
}

int main() {
    /* Build JSON object */
    json_value *obj = json_object_new(4);

    json_value *greeting = json_string("hi");
    json_object_set(obj, "greeting", greeting);

    json_value *n = json_number(42);
    json_object_set(obj, "n", n);

    json_value *list = json_array_new(4);
    json_array_append(list, json_number(1));
    json_array_append(list, json_number(2));
    json_array_append(list, json_number(3));
    json_object_set(obj, "list", list);

    /* Stringify */
    char *str = json_stringify(obj);
    /* printf("Stringified: %s\n", str); */

    /* Parse back */
    json_value *parsed = json_parse(str);

    /* Extract fields */
    json_value *greeting_val = json_object_get(parsed, "greeting");
    json_value *n_val = json_object_get(parsed, "n");
    json_value *list_val = json_object_get(parsed, "list");

    /* Print results */
    if (greeting_val && greeting_val->type == JSON_STRING) {
        printf("%s\n", greeting_val->u.string);
    }
    if (n_val && n_val->type == JSON_NUMBER) {
        printf("%d\n", (int)n_val->u.number);
    }
    if (list_val && list_val->type == JSON_ARRAY) {
        printf("%d\n", (int)list_val->u.array.length);
    }

    /* Cleanup */
    json_free(obj);
    json_free(parsed);
    free(str);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Since we don't have lib/json.aic, we'll implement a minimal JSON library */

typedef enum {
    JSON_NULL,
    JSON_BOOL,
    JSON_INT,
    JSON_STRING,
    JSON_ARRAY,
    JSON_OBJECT
} json_type_t;

typedef struct json_value json_value_t;

struct json_value {
    json_type_t type;
    union {
        int bool_val;
        long long int_val;
        char *string_val;
        struct {
            json_value_t **items;
            size_t size;
            size_t cap;
        } array;
        struct {
            char **keys;
            json_value_t **values;
            size_t size;
            size_t cap;
        } object;
    } u;
};

static json_value_t *json_new(void) {
    json_value_t *v = (json_value_t *)calloc(1, sizeof(json_value_t));
    return v;
}

static void json_free(json_value_t *v) {
    if (!v) return;
    switch (v->type) {
        case JSON_STRING:
            free(v->u.string_val);
            break;
        case JSON_ARRAY:
            for (size_t i = 0; i < v->u.array.size; i++) {
                json_free(v->u.array.items[i]);
            }
            free(v->u.array.items);
            break;
        case JSON_OBJECT:
            for (size_t i = 0; i < v->u.object.size; i++) {
                free(v->u.object.keys[i]);
                json_free(v->u.object.values[i]);
            }
            free(v->u.object.keys);
            free(v->u.object.values);
            break;
        default:
            break;
    }
    free(v);
}

static void json_array_push(json_value_t *arr, json_value_t *item) {
    if (arr->u.array.size >= arr->u.array.cap) {
        arr->u.array.cap = arr->u.array.cap == 0 ? 4 : arr->u.array.cap * 2;
        arr->u.array.items = (json_value_t **)realloc(arr->u.array.items, arr->u.array.cap * sizeof(json_value_t *));
    }
    arr->u.array.items[arr->u.array.size++] = item;
}

static void json_object_set(json_value_t *obj, const char *key, json_value_t *val) {
    if (obj->u.object.size >= obj->u.object.cap) {
        obj->u.object.cap = obj->u.object.cap == 0 ? 4 : obj->u.object.cap * 2;
        obj->u.object.keys = (char **)realloc(obj->u.object.keys, obj->u.object.cap * sizeof(char *));
        obj->u.object.values = (json_value_t **)realloc(obj->u.object.values, obj->u.object.cap * sizeof(json_value_t *));
    }
    obj->u.object.keys[obj->u.object.size] = strdup(key);
    obj->u.object.values[obj->u.object.size] = val;
    obj->u.object.size++;
}

static json_value_t *json_get_object_field(const json_value_t *obj, const char *key) {
    for (size_t i = 0; i < obj->u.object.size; i++) {
        if (strcmp(obj->u.object.keys[i], key) == 0) {
            return (json_value_t *)obj->u.object.values[i];
        }
    }
    return NULL;
}

static json_value_t *json_new_string(const char *s) {
    json_value_t *v = json_new();
    v->type = JSON_STRING;
    v->u.string_val = strdup(s);
    return v;
}

static json_value_t *json_new_int(long long val) {
    json_value_t *v = json_new();
    v->type = JSON_INT;
    v->u.int_val = val;
    return v;
}

static json_value_t *json_new_array(void) {
    json_value_t *v = json_new();
    v->type = JSON_ARRAY;
    v->u.array.items = NULL;
    v->u.array.size = 0;
    v->u.array.cap = 0;
    return v;
}

static json_value_t *json_new_object(void) {
    json_value_t *v = json_new();
    v->type = JSON_OBJECT;
    v->u.object.keys = NULL;
    v->u.object.values = NULL;
    v->u.object.size = 0;
    v->u.object.cap = 0;
    return v;
}

/* Stringify */
static void stringify_value(const json_value_t *v, char **out, size_t *out_len, size_t *out_cap);

static void ensure_capacity(char **out, size_t *out_len, size_t *out_cap, size_t needed) {
    if (*out_len + needed + 1 > *out_cap) {
        while (*out_len + needed + 1 > *out_cap) {
            *out_cap = (*out_cap == 0) ? 64 : *out_cap * 2;
        }
        *out = (char *)realloc(*out, *out_cap);
    }
}

static void append_str(char **out, size_t *out_len, size_t *out_cap, const char *s, size_t len) {
    ensure_capacity(out, out_len, out_cap, len);
    memcpy(*out + *out_len, s, len);
    *out_len += len;
    (*out)[*out_len] = '\0';
}

static void append_char(char **out, size_t *out_len, size_t *out_cap, char c) {
    ensure_capacity(out, out_len, out_cap, 1);
    (*out)[*out_len++] = c;
    (*out)[*out_len] = '\0';
}

static void stringify_string(const char *s, char **out, size_t *out_len, size_t *out_cap) {
    append_char(out, out_len, out_cap, '"');
    for (const char *p = s; *p; p++) {
        switch (*p) {
            case '"': append_str(out, out_len, out_cap, "\\\"", 2); break;
            case '\\': append_str(out, out_len, out_cap, "\\\\", 2); break;
            case '\n': append_str(out, out_len, out_cap, "\\n", 2); break;
            case '\r': append_str(out, out_len, out_cap, "\\r", 2); break;
            case '\t': append_str(out, out_len, out_cap, "\\t", 2); break;
            default: append_char(out, out_len, out_cap, *p); break;
        }
    }
    append_char(out, out_len, out_cap, '"');
}

static void stringify_value(const json_value_t *v, char **out, size_t *out_len, size_t *out_cap) {
    switch (v->type) {
        case JSON_NULL:
            append_str(out, out_len, out_cap, "null", 4);
            break;
        case JSON_BOOL:
            if (v->u.bool_val)
                append_str(out, out_len, out_cap, "true", 4);
            else
                append_str(out, out_len, out_cap, "false", 5);
            break;
        case JSON_INT: {
            char buf[32];
            int len = snprintf(buf, sizeof(buf), "%lld", v->u.int_val);
            append_str(out, out_len, out_cap, buf, len);
            break;
        }
        case JSON_STRING:
            stringify_string(v->u.string_val, out, out_len, out_cap);
            break;
        case JSON_ARRAY: {
            append_char(out, out_len, out_cap, '[');
            for (size_t i = 0; i < v->u.array.size; i++) {
                if (i > 0) append_char(out, out_len, out_cap, ',');
                stringify_value(v->u.array.items[i], out, out_len, out_cap);
            }
            append_char(out, out_len, out_cap, ']');
            break;
        }
        case JSON_OBJECT: {
            append_char(out, out_len, out_cap, '{');
            for (size_t i = 0; i < v->u.object.size; i++) {
                if (i > 0) append_char(out, out_len, out_cap, ',');
                stringify_string(v->u.object.keys[i], out, out_len, out_cap);
                append_char(out, out_len, out_cap, ':');
                stringify_value(v->u.object.values[i], out, out_len, out_cap);
            }
            append_char(out, out_len, out_cap, '}');
            break;
        }
    }
}

char *json_stringify(const json_value_t *v) {
    char *out = NULL;
    size_t out_len = 0, out_cap = 0;
    ensure_capacity(&out, &out_len, &out_cap, 1);
    out_len = 0;
    out[0] = '\0';
    stringify_value(v, &out, &out_len, &out_cap);
    return out;
}

/* Parse */
static const char *parse_value(const char *s, json_value_t **out);
static const char *parse_string(const char *s, char **out_str);
static const char *parse_number(const char *s, json_value_t **out);
static const char *parse_array(const char *s, json_value_t **out);
static const char *parse_object(const char *s, json_value_t **out);

static const char *skip_ws(const char *s) {
    while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
    return s;
}

static const char *parse_string(const char *s, char **out_str) {
    /* s points to opening quote */
    s++; /* skip opening quote */
    char *buf = (char *)malloc(256);
    size_t len = 0;
    while (*s && *s != '"') {
        if (*s == '\\') {
            s++;
            switch (*s) {
                case '"': buf[len++] = '"'; break;
                case '\\': buf[len++] = '\\'; break;
                case 'n': buf[len++] = '\n'; break;
                case 'r': buf[len++] = '\r'; break;
                case 't': buf[len++] = '\t'; break;
                default: buf[len++] = *s; break;
            }
            s++;
        } else {
            buf[len++] = *s++;
        }
    }
    s++; /* skip closing quote */
    buf[len] = '\0';
    *out_str = buf;
    return s;
}

static const char *parse_number(const char *s, json_value_t **out) {
    char *end;
    long long val = strtoll(s, &end, 10);
    json_value_t *v = json_new_int(val);
    *out = v;
    return end;
}

static const char *parse_array(const char *s, json_value_t **out) {
    /* s points to '[' */
    s++; /* skip '[' */
    json_value_t *arr = json_new_array();
    s = skip_ws(s);
    if (*s == ']') {
        s++;
        *out = arr;
        return s;
    }
    while (1) {
        s = skip_ws(s);
        json_value_t *item;
        s = parse_value(s, &item);
        json_array_push(arr, item);
        s = skip_ws(s);
        if (*s == ',') {
            s++;
        } else if (*s == ']') {
            s++;
            break;
        } else {
            break;
        }
    }
    *out = arr;
    return s;
}

static const char *parse_object(const char *s, json_value_t **out) {
    /* s points to '{' */
    s++; /* skip '{' */
    json_value_t *obj = json_new_object();
    s = skip_ws(s);
    if (*s == '}') {
        s++;
        *out = obj;
        return s;
    }
    while (1) {
        s = skip_ws(s);
        char *key;
        s = parse_string(s, &key);
        s = skip_ws(s);
        if (*s != ':') break;
        s++; /* skip ':' */
        s = skip_ws(s);
        json_value_t *val;
        s = parse_value(s, &val);
        json_object_set(obj, key, val);
        free(key);
        s = skip_ws(s);
        if (*s == ',') {
            s++;
        } else if (*s == '}') {
            s++;
            break;
        } else {
            break;
        }
    }
    *out = obj;
    return s;
}

static const char *parse_value(const char *s, json_value_t **out) {
    s = skip_ws(s);
    switch (*s) {
        case '{': return parse_object(s, out);
        case '[': return parse_array(s, out);
        case '"': {
            char *str;
            s = parse_string(s, &str);
            json_value_t *v = json_new_string(str);
            free(str);
            *out = v;
            return s;
        }
        case 't':
            if (strncmp(s, "true", 4) == 0) {
                json_value_t *v = json_new();
                v->type = JSON_BOOL;
                v->u.bool_val = 1;
                *out = v;
                return s + 4;
            }
            break;
        case 'f':
            if (strncmp(s, "false", 5) == 0) {
                json_value_t *v = json_new();
                v->type = JSON_BOOL;
                v->u.bool_val = 0;
                *out = v;
                return s + 5;
            }
            break;
        case 'n':
            if (strncmp(s, "null", 4) == 0) {
                json_value_t *v = json_new();
                v->type = JSON_NULL;
                *out = v;
                return s + 4;
            }
            break;
        default:
            return parse_number(s, out);
    }
    return s;
}

json_value_t *json_parse(const char *s) {
    json_value_t *v;
    parse_value(s, &v);
    return v;
}

