#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Simple JSON implementation for the task */

typedef enum {
    JSON_NULL,
    JSON_BOOL,
    JSON_NUMBER,
    JSON_STRING,
    JSON_ARRAY,
    JSON_OBJECT
} json_type;

typedef struct json_value json_value;

struct json_value {
    json_type type;
    union {
        int bool_val;
        double num_val;
        char *str_val;
        struct {
            json_value **items;
            size_t len;
            size_t cap;
        } arr;
        struct {
            char **keys;
            json_value **vals;
            size_t len;
            size_t cap;
        } obj;
    } u;
};

/* Forward declarations */
json_value *json_new_null(void);
json_value *json_new_bool(int b);
json_value *json_new_number(double n);
json_value *json_new_string(const char *s);
json_value *json_new_array(void);
json_value *json_new_object(void);
void json_free(json_value *v);
char *json_stringify(const json_value *v);
json_value *json_parse(const char *str);

/* Helper: grow array */
static void json_array_append(json_value *arr, json_value *item) {
    if (arr->u.arr.len >= arr->u.arr.cap) {
        size_t newcap = arr->u.arr.cap ? arr->u.arr.cap * 2 : 4;
        arr->u.arr.items = realloc(arr->u.arr.items, newcap * sizeof(json_value *));
        if (!arr->u.arr.items) exit(1);
        arr->u.arr.cap = newcap;
    }
    arr->u.arr.items[arr->u.arr.len++] = item;
}

static void json_object_set(json_value *obj, const char *key, json_value *val) {
    if (obj->u.obj.len >= obj->u.obj.cap) {
        size_t newcap = obj->u.obj.cap ? obj->u.obj.cap * 2 : 4;
        obj->u.obj.keys = realloc(obj->u.obj.keys, newcap * sizeof(char *));
        obj->u.obj.vals = realloc(obj->u.obj.vals, newcap * sizeof(json_value *));
        if (!obj->u.obj.keys || !obj->u.obj.vals) exit(1);
        obj->u.obj.cap = newcap;
    }
    obj->u.obj.keys[obj->u.obj.len] = strdup(key);
    if (!obj->u.obj.keys[obj->u.obj.len]) exit(1);
    obj->u.obj.vals[obj->u.obj.len] = val;
    obj->u.obj.len++;
}

json_value *json_new_null(void) {
    json_value *v = calloc(1, sizeof(json_value));
    if (!v) exit(1);
    v->type = JSON_NULL;
    return v;
}

json_value *json_new_bool(int b) {
    json_value *v = calloc(1, sizeof(json_value));
    if (!v) exit(1);
    v->type = JSON_BOOL;
    v->u.bool_val = b ? 1 : 0;
    return v;
}

json_value *json_new_number(double n) {
    json_value *v = calloc(1, sizeof(json_value));
    if (!v) exit(1);
    v->type = JSON_NUMBER;
    v->u.num_val = n;
    return v;
}

json_value *json_new_string(const char *s) {
    json_value *v = calloc(1, sizeof(json_value));
    if (!v) exit(1);
    v->type = JSON_STRING;
    v->u.str_val = strdup(s);
    if (!v->u.str_val) exit(1);
    return v;
}

json_value *json_new_array(void) {
    json_value *v = calloc(1, sizeof(json_value));
    if (!v) exit(1);
    v->type = JSON_ARRAY;
    v->u.arr.items = NULL;
    v->u.arr.len = 0;
    v->u.arr.cap = 0;
    return v;
}

json_value *json_new_object(void) {
    json_value *v = calloc(1, sizeof(json_value));
    if (!v) exit(1);
    v->type = JSON_OBJECT;
    v->u.obj.keys = NULL;
    v->u.obj.vals = NULL;
    v->u.obj.len = 0;
    v->u.obj.cap = 0;
    return v;
}

void json_free(json_value *v) {
    if (!v) return;
    switch (v->type) {
        case JSON_STRING:
            free(v->u.str_val);
            break;
        case JSON_ARRAY:
            for (size_t i = 0; i < v->u.arr.len; i++)
                json_free(v->u.arr.items[i]);
            free(v->u.arr.items);
            break;
        case JSON_OBJECT:
            for (size_t i = 0; i < v->u.obj.len; i++) {
                free(v->u.obj.keys[i]);
                json_free(v->u.obj.vals[i]);
            }
            free(v->u.obj.keys);
            free(v->u.obj.vals);
            break;
        default:
            break;
    }
    free(v);
}

/* Stringify */
char *json_stringify(const json_value *v) {
    if (!v) return NULL;
    char buf[4096];
    size_t pos = 0;

    switch (v->type) {
        case JSON_NULL:
            pos += sprintf(buf + pos, "null");
            break;
        case JSON_BOOL:
            pos += sprintf(buf + pos, v->u.bool_val ? "true" : "false");
            break;
        case JSON_NUMBER: {
            /* Check if it's an integer */
            if (v->u.num_val == (int)v->u.num_val) {
                pos += sprintf(buf + pos, "%d", (int)v->u.num_val);
            } else {
                pos += sprintf(buf + pos, "%g", v->u.num_val);
            }
            break;
        }
        case JSON_STRING: {
            pos += sprintf(buf + pos, "\"");
            for (const char *p = v->u.str_val; *p; p++) {
                switch (*p) {
                    case '"': pos += sprintf(buf + pos, "\\\""); break;
                    case '\\': pos += sprintf(buf + pos, "\\\\"); break;
                    case '\n': pos += sprintf(buf + pos, "\\n"); break;
                    case '\t': pos += sprintf(buf + pos, "\\t"); break;
                    case '\r': pos += sprintf(buf + pos, "\\r"); break;
                    default: pos += sprintf(buf + pos, "%c", *p); break;
                }
            }
            pos += sprintf(buf + pos, "\"");
            break;
        }
        case JSON_ARRAY: {
            pos += sprintf(buf + pos, "[");
            for (size_t i = 0; i < v->u.arr.len; i++) {
                if (i > 0) pos += sprintf(buf + pos, ",");
                char *item_str = json_stringify(v->u.arr.items[i]);
                if (!item_str) return NULL;
                pos += sprintf(buf + pos, "%s", item_str);
                free(item_str);
            }
            pos += sprintf(buf + pos, "]");
            break;
        }
        case JSON_OBJECT: {
            pos += sprintf(buf + pos, "{");
            for (size_t i = 0; i < v->u.obj.len; i++) {
                if (i > 0) pos += sprintf(buf + pos, ",");
                char *key_str = json_stringify(json_new_string(v->u.obj.keys[i]));
                if (!key_str) return NULL;
                char *val_str = json_stringify(v->u.obj.vals[i]);
                if (!val_str) {
                    free(key_str);
                    return NULL;
                }
                pos += sprintf(buf + pos, "%s:%s", key_str, val_str);
                free(key_str);
                free(val_str);
            }
            pos += sprintf(buf + pos, "}");
            break;
        }
    }

    char *result = malloc(pos + 1);
    if (!result) return NULL;
    memcpy(result, buf, pos);
    result[pos] = '\0';
    return result;
}

/* Parse */
static const char *skip_whitespace(const char *s) {
    while (*s && (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r'))
        s++;
    return s;
}

static json_value *parse_value(const char **ptr);

static json_value *parse_string(const char **ptr) {
    /* Assume *ptr points to opening quote */
    (*ptr)++; /* skip opening quote */
    char *buf = malloc(256);
    if (!buf) return NULL;
    size_t len = 0;

    while (**ptr && **ptr != '"') {
        if (**ptr == '\\') {
            (*ptr)++;
            switch (**ptr) {
                case '"': buf[len++] = '"'; break;
                case '\\': buf[len++] = '\\'; break;
                case 'n': buf[len++] = '\n'; break;
                case 't': buf[len++] = '\t'; break;
                case 'r': buf[len++] = '\r'; break;
                default: buf[len++] = **ptr; break;
            }
        } else {
            buf[len++] = **ptr;
        }
        (*ptr)++;
    }
    if (**ptr != '"') {
        free(buf);
        return NULL;
    }
    (*ptr)++; /* skip closing quote */
    buf[len] = '\0';
    json_value *v = json_new_string(buf);
    free(buf);
    return v;
}

static json_value *parse_number(const char **ptr) {
    char *end;
    double num = strtod(*ptr, &end);
    *ptr = end;
    return json_new_number(num);
}

static json_value *parse_array(const char **ptr) {
    (*ptr)++; /* skip [ */
    json_value *arr = json_new_array();
    *ptr = skip_whitespace(*ptr);
    if (**ptr == ']') {
        (*ptr)++;
        return arr;
    }
    while (1) {
        *ptr = skip_whitespace(*ptr);
        json_value *item = parse_value(ptr);
        if (!item) {
            json_free(arr);
            return NULL;
        }
        json_array_append(arr, item);
        *ptr = skip_whitespace(*ptr);
        if (**ptr == ',') {
            (*ptr)++;
            continue;
        } else if (**ptr == ']') {
            (*ptr)++;
            break;
        } else {
            json_free(arr);
            return NULL;
        }
    }
    return arr;
}

static json_value *parse_object(const char **ptr) {
    (*ptr)++; /* skip { */
    json_value *obj = json_new_object();
    *ptr = skip_whitespace(*ptr);
    if (**ptr == '}') {
        (*ptr)++;
        return obj;
    }
    while (1) {
        *ptr = skip_whitespace(*ptr);
        if (**ptr != '"') {
            json_free(obj);
            return NULL;
        }
        json_value *key = parse_string(ptr);
        if (!key) {
            json_free(obj);
            return NULL;
        }
        *ptr = skip_whitespace(*ptr);
        if (**ptr != ':') {
            json_free(key);
            json_free(obj);
            return NULL;
        }
        (*ptr)++; /* skip : */
        *ptr = skip_whitespace(*ptr);
        json_value *val = parse_value(ptr);
        if (!val) {
            json_free(key);
            json_free(obj);
            return NULL;
        }
        json_object_set(obj, key->u.str_val, val);
        json_free(key);
        *ptr = skip_whitespace(*ptr);
        if (**ptr == ',') {
            (*ptr)++;
            continue;
        } else if (**ptr == '}') {
            (*ptr)++;
            break;
        } else {
            json_free(obj);
            return NULL;
        }
    }
    return obj;
}

static json_value *parse_value(const char **ptr) {
    *ptr = skip_whitespace(*ptr);
    switch (**ptr) {
        case 'n':
            if (strncmp(*ptr, "null", 4) == 0) {
                *ptr += 4;
                return json_new_null();
            }
            return NULL;
        case 't':
            if (strncmp(*ptr, "true", 4) == 0) {
                *ptr += 4;
                return json_new_bool(1);
            }
            return NULL;
        case 'f':
            if (strncmp(*ptr, "false", 5) == 0) {
                *ptr += 5;
                return json_new_bool(0);
            }
            return NULL;
        case '"':
            return parse_string(ptr);
        case '[':
            return parse_array(ptr);
        case '{':
            return parse_object(ptr);
        default:
            if (**ptr == '-' || (**ptr >= '0' && **ptr <= '9')) {
                return parse_number(ptr);
            }
            return NULL;
    }
}

json_value *json_parse(const char *str) {
    const char *ptr = str;
    json_value *v = parse_value(&ptr);
    return v;
}

