/* Arena implementation */
typedef struct {
    unsigned char *base;
    size_t size;
    size_t offset;
} Arena;

/* Initialize arena with given size */
Arena arena_init(size_t size) {
    Arena a;
    a.base = (unsigned char *)malloc(size);
    if (!a.base) {
        fprintf(stderr, "Failed to allocate arena\n");
        exit(1);
    }
    a.size = size;
    a.offset = 0;
    return a;
}

/* Allocate from arena, returns pointer or NULL if not enough space */
void *arena_alloc(Arena *a, size_t size) {
    /* Align to 8 bytes */
    size = (size + 7) & ~7;
    if (a->offset + size > a->size) {
        return NULL;
    }
    void *ptr = a->base + a->offset;
    a->offset += size;
    return ptr;
}

/* Reset arena (set offset back to 0) */
void arena_reset(Arena *a) {
    a->offset = 0;
}

/* Get current offset */
size_t arena_offset(Arena *a) {
    return a->offset;
}

/* Free arena */
void arena_free(Arena *a) {
    free(a->base);
}

