#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Minimal JSON library implementation */

typedef enum {
    JSON_NULL,
    JSON_STRING,
    JSON_NUMBER,
    JSON_OBJECT,
    JSON_ARRAY,
    JSON_BOOL
} json_type;

typedef struct json_value json_value;
typedef struct json_member json_member;
typedef struct json_array json_array;

struct json_member {
    char *key;
    json_value *value;
};

struct json_array {
    json_value **items;
    size_t count;
    size_t capacity;
};

struct json_value {
    json_type type;
    union {
        char *string;
        double number;
        int boolean;
        struct {
            json_member *members;
            size_t count;
            size_t capacity;
        } object;
        json_array array;
    } data;
};

/* Helper functions */

static json_value *json_new_string(const char *str) {
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    v->type = JSON_STRING;
    v->data.string = strdup(str);
    return v;
}

static json_value *json_new_number(double num) {
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    v->type = JSON_NUMBER;
    v->data.number = num;
    return v;
}

static json_value *json_new_object(void) {
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    v->type = JSON_OBJECT;
    v->data.object.members = NULL;
    v->data.object.count = 0;
    v->data.object.capacity = 0;
    return v;
}

static json_value *json_new_array(void) {
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    v->type = JSON_ARRAY;
    v->data.array.items = NULL;
    v->data.array.count = 0;
    v->data.array.capacity = 0;
    return v;
}

static void json_object_add_member(json_value *obj, const char *key, json_value *value) {
    if (obj->data.object.count >= obj->data.object.capacity) {
        size_t new_cap = obj->data.object.capacity ? obj->data.object.capacity * 2 : 4;
        obj->data.object.members = (json_member *)realloc(obj->data.object.members, new_cap * sizeof(json_member));
        obj->data.object.capacity = new_cap;
    }
    obj->data.object.members[obj->data.object.count].key = strdup(key);
    obj->data.object.members[obj->data.object.count].value = value;
    obj->data.object.count++;
}

static void json_array_append(json_value *arr, json_value *value) {
    if (arr->data.array.count >= arr->data.array.capacity) {
        size_t new_cap = arr->data.array.capacity ? arr->data.array.capacity * 2 : 4;
        arr->data.array.items = (json_value **)realloc(arr->data.array.items, new_cap * sizeof(json_value *));
        arr->data.array.capacity = new_cap;
    }
    arr->data.array.items[arr->data.array.count++] = value;
}

static json_value *json_object_get_member(const json_value *obj, const char *key) {
    for (size_t i = 0; i < obj->data.object.count; i++) {
        if (strcmp(obj->data.object.members[i].key, key) == 0) {
            return obj->data.object.members[i].value;
        }
    }
    return NULL;
}

/* Stringify */

static void stringify_value(const json_value *v, char **buf, size_t *pos, size_t *cap) {
    /* Ensure buffer capacity */
    #define ENSURE(n) do { \
        if (*pos + (n) >= *cap) { \
            *cap = *cap ? *cap * 2 : 64; \
            while (*pos + (n) >= *cap) *cap *= 2; \
            *buf = (char *)realloc(*buf, *cap); \
        } \
    } while(0)

    switch (v->type) {
        case JSON_NULL:
            ENSURE(4);
            memcpy(*buf + *pos, "null", 4);
            *pos += 4;
            break;
        case JSON_STRING:
            ENSURE(1);
            *buf[(*pos)++] = '"';
            for (const char *p = v->data.string; *p; p++) {
                switch (*p) {
                    case '"': ENSURE(2); strcpy(*buf + *pos, "\\\""); *pos += 2; break;
                    case '\\': ENSURE(2); strcpy(*buf + *pos, "\\\\"); *pos += 2; break;
                    case '\n': ENSURE(2); strcpy(*buf + *pos, "\\n"); *pos += 2; break;
                    case '\r': ENSURE(2); strcpy(*buf + *pos, "\\r"); *pos += 2; break;
                    case '\t': ENSURE(2); strcpy(*buf + *pos, "\\t"); *pos += 2; break;
                    default: ENSURE(1); *buf[(*pos)++] = *p; break;
                }
            }
            ENSURE(1);
            *buf[(*pos)++] = '"';
            break;
        case JSON_NUMBER: {
            char tmp[64];
            if (v->data.number == (long long)v->data.number && v->data.number >= -2147483648.0 && v->data.number <= 2147483647.0) {
                snprintf(tmp, sizeof(tmp), "%lld", (long long)v->data.number);
            } else {
                snprintf(tmp, sizeof(tmp), "%g", v->data.number);
            }
            size_t len = strlen(tmp);
            ENSURE(len);
            memcpy(*buf + *pos, tmp, len);
            *pos += len;
            break;
        }
        case JSON_BOOL:
            if (v->data.boolean) {
                ENSURE(4);
                memcpy(*buf + *pos, "true", 4);
                *pos += 4;
            } else {
                ENSURE(5);
                memcpy(*buf + *pos, "false", 5);
                *pos += 5;
            }
            break;
        case JSON_OBJECT: {
            ENSURE(1);
            *buf[(*pos)++] = '{';
            for (size_t i = 0; i < v->data.object.count; i++) {
                if (i > 0) {
                    ENSURE(1);
                    *buf[(*pos)++] = ',';
                }
                /* Key */
                ENSURE(1);
                *buf[(*pos)++] = '"';
                for (const char *p = v->data.object.members[i].key; *p; p++) {
                    switch (*p) {
                        case '"': ENSURE(2); strcpy(*buf + *pos, "\\\""); *pos += 2; break;
                        case '\\': ENSURE(2); strcpy(*buf + *pos, "\\\\"); *pos += 2; break;
                        default: ENSURE(1); *buf[(*pos)++] = *p; break;
                    }
                }
                ENSURE(1);
                *buf[(*pos)++] = '"';
                ENSURE(1);
                *buf[(*pos)++] = ':';
                /* Value */
                stringify_value(v->data.object.members[i].value, buf, pos, cap);
            }
            ENSURE(1);
            *buf[(*pos)++] = '}';
            break;
        }
        case JSON_ARRAY: {
            ENSURE(1);
            *buf[(*pos)++] = '[';
            for (size_t i = 0; i < v->data.array.count; i++) {
                if (i > 0) {
                    ENSURE(1);
                    *buf[(*pos)++] = ',';
                }
                stringify_value(v->data.array.items[i], buf, pos, cap);
            }
            ENSURE(1);
            *buf[(*pos)++] = ']';
            break;
        }
    }
}

char *json_stringify(const json_value *v) {
    char *buf = NULL;
    size_t pos = 0, cap = 0;
    stringify_value(v, &buf, &pos, &cap);
    ENSURE(1);
    buf[pos] = '\0';
    return buf;
}

/* Parse */

static const char *skip_whitespace(const char *s) {
    while (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r') s++;
    return s;
}

static json_value *parse_value(const char **s);

static json_value *parse_string(const char **s) {
    if (**s != '"') return NULL;
    (*s)++;
    char *str = (char *)malloc(256);
    size_t len = 0, cap = 256;
    while (**s && **s != '"') {
        if (len + 2 >= cap) {
            cap *= 2;
            str = (char *)realloc(str, cap);
        }
        if (**s == '\\') {
            (*s)++;
            switch (**s) {
                case '"': str[len++] = '"'; break;
                case '\\': str[len++] = '\\'; break;
                case 'n': str[len++] = '\n'; break;
                case 'r': str[len++] = '\r'; break;
                case 't': str[len++] = '\t'; break;
                default: str[len++] = **s; break;
            }
            (*s)++;
        } else {
            str[len++] = **s;
            (*s)++;
        }
    }
    if (**s == '"') (*s)++;
    str[len] = '\0';
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    v->type = JSON_STRING;
    v->data.string = str;
    return v;
}

static json_value *parse_number(const char **s) {
    char *end;
    double num = strtod(*s, &end);
    *s = end;
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    v->type = JSON_NUMBER;
    v->data.number = num;
    return v;
}

static json_value *parse_object(const char **s) {
    if (**s != '{') return NULL;
    (*s)++;
    json_value *v = json_new_object();
    *s = skip_whitespace(*s);
    if (**s == '}') {
        (*s)++;
        return v;
    }
    while (1) {
        *s = skip_whitespace(*s);
        json_value *key = parse_string(s);
        if (!key) break;
        *s = skip_whitespace(*s);
        if (**s != ':') break;
        (*s)++;
        *s = skip_whitespace(*s);
        json_value *val = parse_value(s);
        if (!val) break;
        json_object_add_member(v, key->data.string, val);
        free(key->data.string);
        free(key);
        *s = skip_whitespace(*s);
        if (**s == ',') {
            (*s)++;
            continue;
        } else if (**s == '}') {
            (*s)++;
            break;
        } else {
            break;
        }
    }
    return v;
}

static json_value *parse_array(const char **s) {
    if (**s != '[') return NULL;
    (*s)++;
    json_value *v = json_new_array();
    *s = skip_whitespace(*s);
    if (**s == ']') {
        (*s)++;
        return v;
    }
    while (1) {
        *s = skip_whitespace(*s);
        json_value *val = parse_value(s);
        if (!val) break;
        json_array_append(v, val);
        *s = skip_whitespace(*s);
        if (**s == ',') {
            (*s)++;
            continue;
        } else if (**s == ']') {
            (*s)++;
            break;
        } else {
            break;
        }
    }
    return v;
}

static json_value *parse_value(const char **s) {
    *s = skip_whitespace(*s);
    switch (**s) {
        case '"': return parse_string(s);
        case '{': return parse_object(s);
        case '[': return parse_array(s);
        case 't':
            if (strncmp(*s, "true", 4) == 0) {
                *s += 4;
                json_value *v = (json_value *)calloc(1, sizeof(json_value));
                v->type = JSON_BOOL;
                v->data.boolean = 1;
                return v;
            }
            return NULL;
        case 'f':
            if (strncmp(*s, "false", 5) == 0) {
                *s += 5;
                json_value *v = (json_value *)calloc(1, sizeof(json_value));
                v->type = JSON_BOOL;
                v->data.boolean = 0;
                return v;
            }
            return NULL;
        case 'n':
            if (strncmp(*s, "null", 4) == 0) {
                *s += 4;
                json_value *v = (json_value *)calloc(1, sizeof(json_value));
                v->type = JSON_NULL;
                return v;
            }
            return NULL;
        default:
            if (**s == '-' || (**s >= '0' && **s <= '9')) {
                return parse_number(s);
            }
            return NULL;
    }
}

json_value *json_parse(const char *str) {
    const char *s = str;
    return parse_value(&s);
}

/* Main */

int main(void) {
    /* Build JSON object */
    json_value *root = json_new_object();
    json_object_add_member(root, "greeting", json_new_string("hi"));
    json_object_add_member(root, "n", json_new_number(42));

    json_value *arr = json_new_array();
    json_array_append(arr, json_new_number(1));
    json_array_append(arr, json_new_number(2));
    json_array_append(arr, json_new_number(3));
    json_object_add_member(root, "list", arr);

    /* Stringify */
    char *json_str = json_stringify(root);
    printf("%s\n", json_str);

    /* Parse back */
    json_value *parsed = json_parse(json_str);

    /* Extract fields */
    json_value *greeting = json_object_get_member(parsed, "greeting");
    json_value *n = json_object_get_member(parsed, "n");
    json_value *list = json_object_get_member(parsed, "list");

    /* Print results */
    printf("%s\n", greeting->data.string);
    printf("%lld\n", (long long)n->data.number);
    printf("%zu\n", list->data.array.count);

    /* Cleanup */
    free(json_str);
    return 0;
}

#include <stdio.h>
