/* Simulating the arena.h interface based on common arena allocation patterns */
/* Since we don't have the actual lib/arena.aic, we'll implement a minimal arena */

typedef struct Arena {
    char *mem;
    size_t size;
    size_t offset;
} Arena;

Arena* arena_create(size_t size) {
    Arena *a = (Arena*)malloc(sizeof(Arena));
    if (!a) return NULL;
    a->mem = (char*)malloc(size);
    if (!a->mem) {
        free(a);
        return NULL;
    }
    a->size = size;
    a->offset = 0;
    return a;
}

void arena_destroy(Arena *a) {
    if (a) {
        if (a->mem) free(a->mem);
        free(a);
    }
}

void *arena_alloc(Arena *a, size_t size) {
    if (!a || a->offset + size > a->size) {
        return NULL;
    }
    void *ptr = a->mem + a->offset;
    a->offset += size;
    return ptr;
}

void arena_reset(Arena *a) {
    if (a) {
        a->offset = 0;
    }
}

size_t arena_offset(const Arena *a) {
    if (!a) return 0;
    return a->offset;
}

int main() {
    Arena *arena = arena_create(1024);
    if (!arena) {
        fprintf(stderr, "Failed to create arena\n");
        return 1;
    }

    /* Allocate 3 chunks: 4 bytes, 8 bytes, 16 bytes */
    void *p1 = arena_alloc(arena, 4);
    void *p2 = arena_alloc(arena, 8);
    void *p3 = arena_alloc(arena, 16);

    if (!p1 || !p2 || !p3) {
        fprintf(stderr, "Failed to allocate chunks\n");
        arena_destroy(arena);
        return 1;
    }

    /* Record the arena offset after the 3 allocations */
    size_t offset_after_alloc = arena_offset(arena);

    /* Reset the arena */
    arena_reset(arena);

    /* Print the arena offset after reset (must be 0) */
    printf("%zu\n", arena_offset(arena));

    arena_destroy(arena);
    return 0;
}

