typedef struct {
    unsigned char *data;
    size_t capacity;
    size_t offset;
} Arena;

/* Initialize arena */
static void arena_init(Arena *a, size_t capacity) {
    a->data = (unsigned char *)malloc(capacity);
    a->capacity = capacity;
    a->offset = 0;
}

/* Allocate a chunk from the arena */
static void *arena_alloc(Arena *a, size_t size) {
    /* Align to 8 bytes for simplicity */
    size_t aligned_size = (size + 7) & ~7;
    if (a->offset + aligned_size > a->capacity) {
        return NULL;
    }
    void *ptr = a->data + a->offset;
    a->offset += aligned_size;
    return ptr;
}

/* Reset the arena */
static void arena_reset(Arena *a) {
    a->offset = 0;
}

/* Get the current offset */
static size_t arena_offset(const Arena *a) {
    return a->offset;
}

