#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Simple JSON parser/builder using aic-style API */

typedef enum {
    JSON_NULL,
    JSON_BOOL,
    JSON_INT,
    JSON_DOUBLE,
    JSON_STRING,
    JSON_ARRAY,
    JSON_OBJECT
} json_type_t;

typedef struct json_value json_value_t;

struct json_value {
    json_type_t type;
    union {
        int boolean;
        long long int_val;
        double double_val;
        char *string;
        struct {
            json_value_t **items;
            size_t len;
            size_t cap;
        } array;
        struct {
            struct {
                char *key;
                json_value_t *value;
            } *pairs;
            size_t len;
            size_t cap;
        } object;
    } u;
};

/* Forward declarations */
void json_free(json_value_t *val);
json_value_t *json_parse(const char *str);
char *json_stringify(const json_value_t *val);

/* Helper: create new json value */
json_value_t *json_new(json_type_t type) {
    json_value_t *v = (json_value_t *)calloc(1, sizeof(json_value_t));
    v->type = type;
    return v;
}

void json_free(json_value_t *val) {
    if (!val) return;
    switch (val->type) {
        case JSON_STRING:
            free(val->u.string);
            break;
        case JSON_ARRAY:
            for (size_t i = 0; i < val->u.array.len; i++) {
                json_free(val->u.array.items[i]);
            }
            free(val->u.array.items);
            break;
        case JSON_OBJECT:
            for (size_t i = 0; i < val->u.object.len; i++) {
                free(val->u.object.pairs[i].key);
                json_free(val->u.object.pairs[i].value);
            }
            free(val->u.object.pairs);
            break;
        default:
            break;
    }
    free(val);
}

/* Add to array */
void json_array_append(json_value_t *arr, json_value_t *val) {
    if (arr->type != JSON_ARRAY) return;
    if (arr->u.array.len >= arr->u.array.cap) {
        arr->u.array.cap = arr->u.array.cap ? arr->u.array.cap * 2 : 4;
        arr->u.array.items = (json_value_t **)realloc(arr->u.array.items, arr->u.array.cap * sizeof(json_value_t *));
    }
    arr->u.array.items[arr->u.array.len++] = val;
}

/* Add to object */
void json_object_set(json_value_t *obj, const char *key, json_value_t *val) {
    if (obj->type != JSON_OBJECT) return;
    if (obj->u.object.len >= obj->u.object.cap) {
        obj->u.object.cap = obj->u.object.cap ? obj->u.object.cap * 2 : 4;
        obj->u.object.pairs = (struct { char *key; json_value_t *value; } *)realloc(
            obj->u.object.pairs, obj->u.object.cap * sizeof(obj->u.object.pairs[0])
        );
    }
    obj->u.object.pairs[obj->u.object.len].key = strdup(key);
    obj->u.object.pairs[obj->u.object.len].value = val;
    obj->u.object.len++;
}

/* Get from object by key */
json_value_t *json_object_get(const json_value_t *obj, const char *key) {
    if (obj->type != JSON_OBJECT) return NULL;
    for (size_t i = 0; i < obj->u.object.len; i++) {
        if (strcmp(obj->u.object.pairs[i].key, key) == 0) {
            return obj->u.object.pairs[i].value;
        }
    }
    return NULL;
}

/* Create typed values */
json_value_t *json_new_string(const char *s) {
    json_value_t *v = json_new(JSON_STRING);
    v->u.string = strdup(s);
    return v;
}

json_value_t *json_new_int(long long n) {
    json_value_t *v = json_new(JSON_INT);
    v->u.int_val = n;
    return v;
}

json_value_t *json_new_array(void) {
    return json_new(JSON_ARRAY);
}

json_value_t *json_new_object(void) {
    return json_new(JSON_OBJECT);
}

/* Stringify */
char *json_stringify(const json_value_t *val) {
    if (!val) return NULL;

    size_t buf_size = 1024;
    char *buf = (char *)malloc(buf_size);
    size_t pos = 0;

    #define APPEND(...) \
        do { \
            int _n = snprintf(buf + pos, buf_size - pos, __VA_ARGS__); \
            if (_n < 0 || (size_t)_n >= buf_size - pos) { \
                /* expand */ \
                while (_n >= (int)(buf_size - pos)) { \
                    buf_size *= 2; \
                    buf = (char *)realloc(buf, buf_size); \
                } \
                _n = snprintf(buf + pos, buf_size - pos, __VA_ARGS__); \
            } \
            pos += _n; \
        } while(0)

    #define APPEND_STR(s) \
        do { \
            size_t _len = strlen(s); \
            while (pos + _len + 1 >= buf_size) { \
                buf_size *= 2; \
                buf = (char *)realloc(buf, buf_size); \
            } \
            memcpy(buf + pos, s, _len + 1); \
            pos += _len; \
        } while(0)

    switch (val->type) {
        case JSON_NULL:
            APPEND("null");
            break;
        case JSON_BOOL:
            APPEND(val->u.boolean ? "true" : "false");
            break;
        case JSON_INT:
            APPEND("%lld", val->u.int_val);
            break;
        case JSON_DOUBLE:
            APPEND("%g", val->u.double_val);
            break;
        case JSON_STRING: {
            APPEND("\"");
            for (const char *p = val->u.string; *p; p++) {
                switch (*p) {
                    case '"': APPEND("\\\""); break;
                    case '\\': APPEND("\\\\"); break;
                    case '\n': APPEND("\\n"); break;
                    case '\r': APPEND("\\r"); break;
                    case '\t': APPEND("\\t"); break;
                    default: APPEND("%c", *p); break;
                }
            }
            APPEND("\"");
            break;
        }
        case JSON_ARRAY: {
            APPEND("[");
            for (size_t i = 0; i < val->u.array.len; i++) {
                if (i > 0) APPEND(",");
                char *sub = json_stringify(val->u.array.items[i]);
                if (sub) {
                    APPEND_STR(sub);
                    free(sub);
                }
            }
            APPEND("]");
            break;
        }
        case JSON_OBJECT: {
            APPEND("{");
            for (size_t i = 0; i < val->u.object.len; i++) {
                if (i > 0) APPEND(",");
                char *key_str = json_stringify(json_new_string(val->u.object.pairs[i].key));
                if (key_str) {
                    APPEND_STR(key_str);
                    free(key_str);
                }
                APPEND(":");
                char *val_str = json_stringify(val->u.object.pairs[i].value);
                if (val_str) {
                    APPEND_STR(val_str);
                    free(val_str);
                }
            }
            APPEND("}");
            break;
        }
    }

    buf[pos] = '\0';
    #undef APPEND
    #undef APPEND_STR
    return buf;
}

/* Parse */
static const char *parse_value(const char *p, json_value_t **out);

static void skip_ws(const char **p) {
    while (**p && (**p == ' ' || **p == '\t' || **p == '\n' || **p == '\r')) {
        (*p)++;
    }
}

static const char *parse_string(const char *p, char **out) {
    if (*p != '"') return NULL;
    p++;
    size_t len = 0;
    char *buf = (char *)malloc(128);
    while (*p && *p != '"') {
        if (len + 2 >= 128) {
            /* expand */
            static size_t cap = 128;
            cap *= 2;
            buf = (char *)realloc(buf, cap);
        }
        if (*p == '\\') {
            p++;
            switch (*p) {
                case '"': buf[len++] = '"'; break;
                case '\\': buf[len++] = '\\'; break;
                case 'n': buf[len++] = '\n'; break;
                case 'r': buf[len++] = '\r'; break;
                case 't': buf[len++] = '\t'; break;
                default: buf[len++] = *p; break;
            }
            p++;
        } else {
            buf[len++] = *p++;
        }
    }
    if (*p != '"') {
        free(buf);
        return NULL;
    }
    p++;
    buf[len] = '\0';
    *out = buf;
    return p;
}

static const char *parse_number(const char *p, json_value_t **out) {
    char *end;
    long long val = strtoll(p, &end, 10);
    if (end == p) {
        /* try double */
        double dval = strtod(p, &end);
        if (end == p) return NULL;
        json_value_t *v = json_new(JSON_DOUBLE);
        v->u.double_val = dval;
        *out = v;
        return end;
    }
    json_value_t *v = json_new(JSON_INT);
    v->u.int_val = val;
    *out = v;
    return end;
}

static const char *parse_array(const char *p, json_value_t **out) {
    p++; /* skip [ */
    json_value_t *arr = json_new(JSON_ARRAY);
    skip_ws(&p);
    if (*p == ']') {
        *out = arr;
        return p + 1;
    }
    while (1) {
        json_value_t *elem;
        p = parse_value(p, &elem);
        if (!p) {
            json_free(arr);
            return NULL;
        }
        json_array_append(arr, elem);
        skip_ws(&p);
        if (*p == ',') {
            p++;
            skip_ws(&p);
        } else if (*p == ']') {
            *out = arr;
            return p + 1;
        } else {
            json_free(arr);
            return NULL;
        }
    }
}

static const char *parse_object(const char *p, json_value_t **out) {
    p++; /* skip { */
    json_value_t *obj = json_new(JSON_OBJECT);
    skip_ws(&p);
    if (*p == '}') {
        *out = obj;
        return p + 1;
    }
    while (1) {
        skip_ws(&p);
        char *key;
        p = parse_string(p, &key);
        if (!p) {
            json_free(obj);
            return NULL;
        }
        skip_ws(&p);
        if (*p != ':') {
            free(key);
            json_free(obj);
            return NULL;
        }
        p++;
        skip_ws(&p);
        json_value_t *val;
        p = parse_value(p, &val);
        if (!p) {
            free(key);
            json_free(obj);
            return NULL;
        }
        json_object_set(obj, key, val);
        free(key);
        skip_ws(&p);
        if (*p == ',') {
            p++;
        } else if (*p == '}') {
            *out = obj;
            return p + 1;
        } else {
            json_free(obj);
            return NULL;
        }
    }
}

static const char *parse_value(const char *p, json_value_t **out) {
    skip_ws(&p);
    switch (*p) {
        case 'n':
            if (strncmp(p, "null", 4) == 0) {
                json_value_t *v = json_new(JSON_NULL);
                *out = v;
                return p + 4;
            }
            return NULL;
        case 't':
            if (strncmp(p, "true", 4) == 0) {
                json_value_t *v = json_new(JSON_BOOL);
                v->u.boolean = 1;
                *out = v;
                return p + 4;
            }
            return NULL;
        case 'f':
            if (strncmp(p, "false", 5) == 0) {
                json_value_t *v = json_new(JSON_BOOL);
                v->u.boolean = 0;
                *out = v;
                return p + 5;
            }
            return NULL;
        case '"': {
            char *s;
            p = parse_string(p, &s);
            if (!p) return NULL;
            json_value_t *v = json_new(JSON_STRING);
            v->u.string = s;
            *out = v;
            return p;
        }
        case '[':
            return parse_array(p, out);
        case '{':
            return parse_object(p, out);
        default:
            if (*p == '-' || (*p >= '0' && *p <= '9')) {
                return parse_number(p, out);
            }
            return NULL;
    }
}

json_value_t *json_parse(const char *str) {
    json_value_t *val;
    const char *p = parse_value(str, &val);
    if (!p) return NULL;
    return val;
}

int main(void) {
    /* Build JSON object */
    json_value_t *obj = json_new_object();
    json_value_t *greeting = json_new_string("hi");
    json_value_t *n = json_new_int(42);
    json_value_t *list = json_new_array();
