    json_object_set(obj, "greeting", greeting);
    json_object_set(obj, "n", n);
    json_object_set(obj, "list", list);

    /* Stringify */
    char *json_str = json_stringify(obj);

    /* Parse back */
    json_value_t *parsed = json_parse(json_str);

    /* Extract values */
    json_value_t *parsed_greeting = json_object_get(parsed, "greeting");
    json_value_t *parsed_n = json_object_get(parsed, "n");
    json_value_t *parsed_list = json_object_get(parsed, "list");

    /* Print results */
    if (parsed_greeting && parsed_greeting->type == JSON_STRING) {
