    }
    if (parsed_list && parsed_list->type == JSON_ARRAY) {
        printf("%zu\n", parsed_list->u.array.len);
    }

    /* Cleanup */
    json_free(parsed);
    json_free(obj);
    free(json_str);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* 
 * Since we don't have the actual lib/json.aic file, I'll implement a minimal 
 * JSON library that provides the necessary functionality.
 */

/* Minimal JSON implementation */

typedef struct {
    char *key;
    void *value;
    int type; /* 0: null, 1: string, 2: int, 3: array, 4: object */
    struct json_value *next;
} json_value;

typedef struct {
    json_value *head;
    json_value *tail;
    int size;
} json_array;

typedef struct {
    json_value *head;
    json_value *tail;
    int size;
} json_object;

typedef struct {
    int type;
    union {
        char *str;
        int num;
        json_array *arr;
        json_object *obj;
    } data;
} json_root;

/* Forward declarations */
json_value *json_new_value(int type);
void json_free_value(json_value *v);
char *json_stringify(json_root *root);
json_root *json_parse(const char *str);

/* Helper functions */
json_value *json_new_value(int type) {
    json_value *v = (json_value *)calloc(1, sizeof(json_value));
    if (!v) return NULL;
    v->type = type;
    v->key = NULL;
    v->value = NULL;
    v->next = NULL;
    return v;
}

void json_free_value(json_value *v) {
    if (!v) return;
    if (v->key) free(v->key);
    if (v->type == 1 && v->value) free(v->value);
    if (v->type == 2 && v->value) {
        /* int is stored directly, no need to free */
    }
    if (v->type == 3 && v->value) {
        json_array *arr = (json_array *)v->value;
        json_value *cur = arr->head;
        while (cur) {
            json_value *next = cur->next;
            json_free_value(cur);
            cur = next;
        }
        free(arr);
    }
    if (v->type == 4 && v->value) {
        json_object *obj = (json_object *)v->value;
        json_value *cur = obj->head;
        while (cur) {
            json_value *next = cur->next;
            json_free_value(cur);
            cur = next;
        }
        free(obj);
    }
    free(v);
}

/* Create a string value */
json_value *json_string(const char *key, const char *val) {
    json_value *v = json_new_value(1);
    if (!v) return NULL;
    v->key = strdup(key);
    v->value = strdup(val);
    return v;
}

/* Create an int value */
json_value *json_int(const char *key, int val) {
    json_value *v = json_new_value(2);
    if (!v) return NULL;
    v->key = strdup(key);
    /* Store int in a malloc'd int */
    int *num = (int *)malloc(sizeof(int));
    *num = val;
    v->value = (void *)num;
    return v;
}

/* Create an array value with int elements */
json_value *json_array_ints(const char *key, int *vals, int count) {
    json_value *v = json_new_value(3);
    if (!v) return NULL;
    v->key = strdup(key);

    json_array *arr = (json_array *)calloc(1, sizeof(json_array));
    if (!arr) {
        free(v->key);
        free(v);
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        json_value *elem = json_new_value(2);
        if (!elem) {
            /* Clean up */
            json_value *cur = arr->head;
            while (cur) {
                json_value *next = cur->next;
                json_free_value(cur);
                cur = next;
            }
            free(arr);
            free(v->key);
            free(v);
            return NULL;
        }
        elem->key = NULL;
        int *num = (int *)malloc(sizeof(int));
        *num = vals[i];
        elem->value = (void *)num;

        if (!arr->head) {
            arr->head = arr->tail = elem;
        } else {
            arr->tail->next = elem;
            arr->tail = elem;
        }
        arr->size++;
    }

    v->value = (void *)arr;
    return v;
}

/* Build a JSON object from values */
json_root *json_build_object(json_value **vals, int count) {
    json_root *root = (json_root *)calloc(1, sizeof(json_root));
    if (!root) return NULL;

    root->type = 4;
    json_object *obj = (json_object *)calloc(1, sizeof(json_object));
    if (!obj) {
        free(root);
        return NULL;
    }

    for (int i = 0; i < count; i++) {
        if (!vals[i]) continue;
        if (!obj->head) {
            obj->head = obj->tail = vals[i];
        } else {
            obj->tail->next = vals[i];
            obj->tail = vals[i];
        }
        obj->size++;
    }

    root->data.obj = obj;
    return root;
}

/* Stringify a JSON root */
char *json_stringify(json_root *root) {
    if (!root) return NULL;

    if (root->type != 4) return NULL;

    json_object *obj = root->data.obj;
    if (!obj || obj->size == 0) {
        char *result = (char *)malloc(3);
        if (result) strcpy(result, "{}");
        return result;
    }

    /* Estimate size */
    size_t total_size = 2; /* for {} */
    json_value *cur = obj->head;
    while (cur) {
        if (cur->key) total_size += strlen(cur->key) + 4; /* "key": */
        if (cur->type == 1 && cur->value) {
            total_size += strlen((char *)cur->value) + 2; /* "value" */
        } else if (cur->type == 2 && cur->value) {
            total_size += 10; /* max int */
        } else if (cur->type == 3 && cur->value) {
            json_array *arr = (json_array *)cur->value;
            total_size += 2; /* for [] */
            for (int i = 0; i < arr->size; i++) {
                total_size += 10; /* max int + comma */
            }
        }
        if (cur->next) total_size += 1; /* comma */
        cur = cur->next;
    }

    char *result = (char *)malloc(total_size + 1);
    if (!result) return NULL;

    char *ptr = result;
    *ptr++ = '{';

    cur = obj->head;
    while (cur) {
        if (cur->key) {
            *ptr++ = '"';
            strcpy(ptr, cur->key);
            ptr += strlen(cur->key);
            *ptr++ = '"';
            *ptr++ = ':';
        }

        if (cur->type == 1 && cur->value) {
            *ptr++ = '"';
            strcpy(ptr, (char *)cur->value);
            ptr += strlen((char *)cur->value);
            *ptr++ = '"';
        } else if (cur->type == 2 && cur->value) {
            int val = *((int *)cur->value);
            ptr += sprintf(ptr, "%d", val);
        } else if (cur->type == 3 && cur->value) {
            json_array *arr = (json_array *)cur->value;
            *ptr++ = '[';
            json_value *elem = arr->head;
            while (elem) {
                if (elem->type == 2 && elem->value) {
                    int val = *((int *)elem->value);
                    ptr += sprintf(ptr, "%d", val);
                }
                if (elem->next) *ptr++ = ',';
                elem = elem->next;
            }
            *ptr++ = ']';
        }

        if (cur->next) *ptr++ = ',';
        cur = cur->next;
    }

    *ptr++ = '}';
    *ptr = '\0';

    return result;
}

/* Parse JSON string */
json_root *json_parse(const char *str) {
    if (!str || strlen(str) < 2) return NULL;

    /* Simple parser for our specific format */
    if (str[0] != '{') return NULL;

    json_root *root = (json_root *)calloc(1, sizeof(json_root));
    if (!root) return NULL;

    root->type = 4;
    json_object *obj = (json_object *)calloc(1, sizeof(json_object));
    if (!obj) {
        free(root);
        return NULL;
    }

    char *s = (char *)str + 1;

    while (*s && *s != '}') {
        /* Skip whitespace */
        while (*s && (*s == ' ' || *s == '\t' || *s == '\n' || *s == '\r')) s++;
        if (*s == '}') break;

        /* Parse key */
        if (*s != '"') break;
        s++;
        char *key_start = s;
        while (*s && *s != '"') s++;
        if (*s != '"') break;
        size_t key_len = s - key_start;
        char *key = (char *)malloc(key_len + 1);
        if (!key) break;
        memcpy(key, key_start, key_len);
        key[key_len] = '\0';
        s++;

        /* Expect ':' */
        while (*s && (*s == ' ' || *s == '\t')) s++;
        if (*s != ':') break;
        s++;
        while (*s && (*s == ' ' || *s == '\t')) s++;

        /* Parse value */
        json_value *v = NULL;

        if (*s == '"') {
            /* String value */
            s++;
            char *val_start = s;
            while (*s && *s != '"') s++;
            if (*s != '"') break;
            size_t val_len = s - val_start;
            char *val = (char *)malloc(val_len + 1);
            if (!val) break;
            memcpy(val, val_start, val_len);
            val[val_len] = '\0';
            s++;

            v = json_new_value(1);
            if (!v) break;
            v->key = key;
            v->value = val;
        } else if (*s == '[') {
            /* Array value */
            s++;
            json_array *arr = (json_array *)calloc(1, sizeof(json_array));
            if (!arr) break;

            while (*s && *s != ']') {
                /* Skip whitespace */
                while (*s && (*s == ' ' || *s == '\t' || *s == ',')) s++;
                if (*s == ']') break;

                /* Parse int */
                char *num_start = s;
                while (*s && (*s >= '0' && *s <= '9' || *s == '-')) s++;
                size_t num_len = s - num_start;
                int num = 0;
                if (num_len > 0) {
                    char *num_str = (char *)malloc(num_len + 1);
                    if (num_str) {
                        memcpy(num_str, num_start, num_len);
                        num_str[num_len] = '\0';
                        num = atoi(num_str);
                        free(num_str);
                    }
                }

                json_value *elem = json_new_value(2);
                if (!elem) break;
                elem->key = NULL;
                int *num_ptr = (int *)malloc(sizeof(int));
                *num_ptr = num;
                elem->value = (void *)num_ptr;

                if (!arr->head) {
                    arr->head = arr->tail = elem;
                } else {
                    arr->tail->next = elem;
                    arr->tail = elem;
                }
                arr->size++;
            }

            if (*s == ']') s++;

            v = json_new_value(3);
            if (!v) break;
            v->key = key;
            v->value = (void *)arr;
        } else {
            /* Int value */
            char *num_start = s;
            while (*s && (*s >= '0' && *s <= '9' || *s == '-')) s++;
            size_t num_len = s - num_start;
            int num = 0;
            if (num_len > 0) {
                char *num_str = (char *)malloc(num_len + 1);
                if (num_str) {
                    memcpy(num_str, num_start, num_len);
                    num_str[num_len] = '\0';
                    num = atoi(num_str);
                    free(num_str);
                }
            }

            v = json_new_value(2);
            if (!v) break;
            v->key = key;
            int *num_ptr = (int *)malloc(sizeof(int));
            *num_ptr = num;
            v->value = (void *)num_ptr;
        }

        if (!v) break;

        if (!obj->head) {
            obj->head = obj->tail = v;
        } else {
            obj->tail->next = v;
            obj->tail = v;
        }
        obj->size++;

        /* Skip whitespace and comma */
        while (*s && (*s == ' ' || *s == '\t')) s++;
        if (*s == ',') s++;
    }

    if (*s == '}') s++;

    root->data.obj = obj;
    return root;
}

void json_free_root(json_root *root) {
    if (!root) return;
    if (root->type == 4 && root->data.obj) {
        json_object *obj = root->data.obj;
        json_value *cur = obj->head;
        while (cur) {
            json_value *next = cur->next;
            json_free_value(cur);
            cur = next;
        }
        free(obj);
    }
    free(root);
}

/* Helper to find a value by key in an object */
json_value *json_find_key(json_root *root, const char *key) {
    if (!root || root->type != 4) return NULL;
    json_object *obj = root->data.obj;
    if (!obj) return NULL;

    json_value *cur = obj->head;
    while (cur) {
        if (cur->key && strcmp(cur->key, key) == 0) {
            return cur;
        }
        cur = cur->next;
    }
    return NULL;
}

int main() {
    /* Build JSON object with:
     * "greeting" = "hi"
     * "n" = 42
     * "list" = [1, 2, 3]
     */

    json_value *greeting = json_string("greeting", "hi");
    json_value *n = json_int("n", 42);

    int list_vals[] = {1, 2, 3};
    json_value *list = json_array_ints("list", list_vals, 3);

    json_value *vals[] = {greeting, n, list};
    json_root *root = json_build_object(vals, 3);

    if (!root) {
        fprintf(stderr, "Failed to build JSON object\n");
        return 1;
    }

    /* Stringify */
    char *json_str = json_stringify(root);
    if (!json_str) {
        fprintf(stderr, "Failed to stringify JSON\n");
        json_free_root(root);
        return 1;
    }

    /* Parse back */
    json_root *parsed = json_parse(json_str);
    if (!parsed) {
        fprintf(stderr, "Failed to parse JSON\n");
        free(json_str);
        json_free_root(root);
        return 1;
    }

    /* Extract fields */
    json_value *greeting_val = json_find_key(parsed, "greeting");
    json_value *n_val = json_find_key(parsed, "n");
    json_value *list_val = json_find_key(parsed, "list");

    /* Print results */
    if (greeting_val && greeting_val->type == 1 && greeting_val->value) {
        printf("%s\n", (char *)greeting_val->value);
    } else {
        printf("null\n");
    }

    if (n_val && n_val->type == 2 && n_val->value) {
        printf("%d\n", *((int *)n_val->value));
    } else {
        printf("0\n");
    }

    if (list_val && list_val->type == 3 && list_val->value) {
        json_array *arr = (json_array *)list_val->value;
        printf("%d\n", arr->size);
    } else {
        printf("0\n");
    }

    /* Cleanup */
    free(json_str);
    json_free_root(root);
    json_free_root(parsed);

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Since we don't have the actual lib/json.aic, I'll implement a minimal JSON
   builder/parser that matches the expected behavior. The task says to use
   lib/json.aic, but since that's not available, I'll create a self-contained
   implementation that does what's described. */

/* Simple JSON object representation */
typedef struct {
    char key[256];
    int type; /* 0: string, 1: int, 2: array */
    char str_val[256];
    int int_val;
    int *arr_val;
    int arr_len;
} JsonField;

typedef struct {
    JsonField fields[32];
    int num_fields;
} JsonObject;

/* Build a JSON object string */
char* json_build(const char *greeting, int n, int *list, int list_len) {
    char *buf = malloc(1024);
    int offset = 0;
    offset += sprintf(buf + offset, "{\"greeting\":\"%s\",", greeting);
    offset += sprintf(buf + offset, "\"n\":%d,", n);
    offset += sprintf(buf + offset, "\"list\":[");
    for (int i = 0; i < list_len; i++) {
        offset += sprintf(buf + offset, "%d%s", list[i], i < list_len - 1 ? "," : "");
    }
    offset += sprintf(buf + offset, "]}");
    return buf;
}

/* Parse a JSON string back into fields */
void json_parse(const char *json, char *greeting_out, int *n_out, int **list_out, int *list_len_out) {
    /* Find "greeting":"..." */
    const char *p = strstr(json, "\"greeting\":\"");
    if (p) {
        p += strlen("\"greeting\":\"");
        const char *end = strchr(p, '"');
        int len = end - p;
        if (len < 256) {
            strncpy(greeting_out, p, len);
            greeting_out[len] = '\0';
        }
    }

    /* Find "n":<int> */
    p = strstr(json, "\"n\":");
    if (p) {
        p += strlen("\"n\":");
        *n_out = atoi(p);
    }

    /* Find "list":[...] */
    p = strstr(json, "\"list\":[");
    if (p) {
        p += strlen("\"list\":[");
        const char *end = strchr(p, ']');
        int list_len = 0;
        *list_out = malloc(64 * sizeof(int));
        char *temp = strdup(p);
        char *token = strtok(temp, ",");
        while (token && list_len < 64) {
            (*list_out)[list_len] = atoi(token);
            list_len++;
            token = strtok(NULL, ",");
        }
        *list_len_out = list_len;
        free(temp);
    }
}

int main() {
    int list[] = {1, 2, 3};
    int list_len = 3;

    /* Build JSON */
    char *json_str = json_build("hi", 42, list, list_len);

    /* Parse back */
    char greeting[256] = "";
    int n = 0;
    int *list_out = NULL;
    int list_len_out = 0;

    json_parse(json_str, greeting, &n, &list_out, &list_len_out);

    /* Print results */
    printf("%s\n", greeting);
    printf("%d\n", n);
    printf("%d\n", list_len_out);

    free(json_str);
    if (list_out) free(list_out);

    return 0;
}

#include <stdio.h>
#include <string.h>

int starts_with(const char *str, const char *prefix) {
    size_t len = strlen(prefix);
    return strncmp(str, prefix, len) == 0;
}

int ends_with(const char *str, const char *suffix) {
