#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Since we don't have the actual lib/json.aic, we need to implement a minimal JSON library */

typedef struct {
    char *key;
    int type; /* 0: string, 1: int, 2: array */
    char *str_val;
    int int_val;
    int *arr_val;
    int arr_len;
} JsonField;

typedef struct {
    JsonField *fields;
    int num_fields;
} JsonObject;

JsonObject* json_new_object() {
    JsonObject *obj = (JsonObject*)calloc(1, sizeof(JsonObject));
    return obj;
}

void json_add_string(JsonObject *obj, const char *key, const char *value) {
    obj->fields = (JsonField*)realloc(obj->fields, (obj->num_fields + 1) * sizeof(JsonField));
    JsonField *f = &obj->fields[obj->num_fields];
    f->key = strdup(key);
    f->type = 0;
    f->str_val = strdup(value);
    f->int_val = 0;
    f->arr_val = NULL;
    f->arr_len = 0;
    obj->num_fields++;
}

void json_add_int(JsonObject *obj, const char *key, int value) {
    obj->fields = (JsonField*)realloc(obj->fields, (obj->num_fields + 1) * sizeof(JsonField));
    JsonField *f = &obj->fields[obj->num_fields];
    f->key = strdup(key);
    f->type = 1;
    f->str_val = NULL;
    f->int_val = value;
    f->arr_val = NULL;
    f->arr_len = 0;
    obj->num_fields++;
}

void json_add_array(JsonObject *obj, const char *key, int *values, int len) {
    obj->fields = (JsonField*)realloc(obj->fields, (obj->num_fields + 1) * sizeof(JsonField));
    JsonField *f = &obj->fields[obj->num_fields];
    f->key = strdup(key);
    f->type = 2;
    f->str_val = NULL;
    f->int_val = 0;
    f->arr_val = (int*)malloc(len * sizeof(int));
    memcpy(f->arr_val, values, len * sizeof(int));
    f->arr_len = len;
    obj->num_fields++;
}

char* json_stringify(JsonObject *obj) {
    /* Estimate size: each field adds roughly 50 chars plus key/value lengths */
    int size = 1;
    for (int i = 0; i < obj->num_fields; i++) {
        size += strlen(obj->fields[i].key) + 20;
        if (obj->fields[i].type == 0) {
            size += strlen(obj->fields[i].str_val) + 5;
        } else if (obj->fields[i].type == 2) {
            size += obj->fields[i].arr_len * 10 + 5;
        }
    }
    char *buf = (char*)malloc(size);
    buf[0] = '\0';
    strcat(buf, "{");
    for (int i = 0; i < obj->num_fields; i++) {
        if (i > 0) strcat(buf, ",");
        JsonField *f = &obj->fields[i];
        char tmp[512];
        if (f->type == 0) {
            snprintf(tmp, sizeof(tmp), "\"%s\":\"%s\"", f->key, f->str_val);
        } else if (f->type == 1) {
            snprintf(tmp, sizeof(tmp), "\"%s\":%d", f->key, f->int_val);
        } else if (f->type == 2) {
            tmp[0] = '\0';
            char keypart[256];
            snprintf(keypart, sizeof(keypart), "\"%s\":[", f->key);
            strcat(tmp, keypart);
            for (int j = 0; j < f->arr_len; j++) {
                char num[32];
                snprintf(num, sizeof(num), "%d", f->arr_val[j]);
                strcat(tmp, num);
                if (j < f->arr_len - 1) strcat(tmp, ",");
            }
            strcat(tmp, "]");
        }
        strcat(buf, tmp);
    }
    strcat(buf, "}");
    return buf;
}

/* Simple JSON parser */
JsonObject* json_parse(const char *str) {
    JsonObject *obj = json_new_object();
    /* Skip to '{' */
    const char *p = str;
    while (*p && *p != '{') p++;
    if (*p != '{') return obj;
    p++; /* skip '{' */

    while (*p) {
        /* Skip whitespace */
        while (*p && (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r')) p++;
        if (*p == '}') { p++; break; }
        if (*p == ',') { p++; continue; }
        if (*p != '"') break;

        /* Parse key */
        p++; /* skip '"' */
        char key[256];
        int ki = 0;
        while (*p && *p != '"') {
            key[ki++] = *p++;
        }
        key[ki] = '\0';
        p++; /* skip closing '"' */

        /* Skip whitespace */
        while (*p && (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r')) p++;
        if (*p != ':') break;
        p++; /* skip ':' */

        /* Skip whitespace */
        while (*p && (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r')) p++;

        if (*p == '"') {
            /* String value */
            p++; /* skip '"' */
            char val[256];
            int vi = 0;
            while (*p && *p != '"') {
                val[vi++] = *p++;
            }
            val[vi] = '\0';
            p++; /* skip closing '"' */
            json_add_string(obj, key, val);
        } else if (*p == '[') {
            /* Array value */
            p++; /* skip '[' */
            int *arr = NULL;
            int len = 0;
            while (*p) {
                while (*p && (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r')) p++;
                if (*p == ']') { p++; break; }
                if (*p == ',') { p++; continue; }
                /* Parse number */
                char num[64];
                int ni = 0;
                while (*p && *p != ',' && *p != ']') {
                    num[ni++] = *p++;
                }
                num[ni] = '\0';
                arr = (int*)realloc(arr, (len + 1) * sizeof(int));
                arr[len++] = atoi(num);
            }
            json_add_array(obj, key, arr, len);
            free(arr);
        } else {
            /* Number */
            char num[64];
            int ni = 0;
            while (*p && *p != ',' && *p != '}' && *p != ' ' && *p != '\t' && *p != '\n' && *p != '\r') {
                num[ni++] = *p++;
            }
            num[ni] = '\0';
            json_add_int(obj, key, atoi(num));
        }

        /* Skip whitespace */
        while (*p && (*p == ' ' || *p == '\t' || *p == '\n' || *p == '\r')) p++;
    }

    return obj;
}

const char* json_get_string(JsonObject *obj, const char *key) {
    for (int i = 0; i < obj->num_fields; i++) {
        if (strcmp(obj->fields[i].key, key) == 0 && obj->fields[i].type == 0) {
            return obj->fields[i].str_val;
        }
    }
    return NULL;
}

int json_get_int(JsonObject *obj, const char *key) {
    for (int i = 0; i < obj->num_fields; i++) {
        if (strcmp(obj->fields[i].key, key) == 0 && obj->fields[i].type == 1) {
            return obj->fields[i].int_val;
        }
    }
    return 0;
}

int json_get_array_len(JsonObject *obj, const char *key) {
    for (int i = 0; i < obj->num_fields; i++) {
        if (strcmp(obj->fields[i].key, key) == 0 && obj->fields[i].type == 2) {
            return obj->fields[i].arr_len;
        }
    }
    return -1;
}

int main() {
    /* Build JSON object */
    JsonObject *obj = json_new_object();
    json_add_string(obj, "greeting", "hi");
    json_add_int(obj, "n", 42);
    int arr[] = {1, 2, 3};
    json_add_array(obj, "list", arr, 3);

    /* Stringify */
    char *str = json_stringify(obj);

    /* Parse back */
    JsonObject *recovered = json_parse(str);

    /* Print results */
    const char *greeting = json_get_string(recovered, "greeting");
    int n = json_get_int(recovered, "n");
    int list_len = json_get_array_len(recovered, "list");

    printf("%s\n", greeting);
    printf("%d\n", n);
    printf("%d\n", list_len);

    /* Cleanup */
    free(str);
    return 0;
}

