    MapEntry entries[MAX_ENTRIES];
    int size;
} StringMap;

void map_init(StringMap *map) {
    map->size = 0;
    for (int i = 0; i < MAX_ENTRIES; i++) {
        map->entries[i].key = NULL;
        map->entries[i].count = 0;
    }
}

void map_insert(StringMap *map, const char *key) {
    for (int i = 0; i < map->size; i++) {
        if (strcmp(map->entries[i].key, key) == 0) {
            map->entries[i].count++;
            return;
        }
    }
    if (map->size < MAX_ENTRIES) {
        map->entries[map->size].key = key;
        map->entries[map->size].count = 1;
        map->size++;
    }
}

int map_get(StringMap *map, const char *key) {
    for (int i = 0; i < map->size; i++) {
        if (strcmp(map->entries[i].key, key) == 0) {
            return map->entries[i].count;
        }
    }
    return 0;
}

