/* Simple map implementation using an array of key-value pairs */
#define MAP_CAPACITY 128

typedef struct {
    char *key;
    int count;
} MapEntry;

typedef struct {
    MapEntry entries[MAP_CAPACITY];
    int size;
} Map;

void map_init(Map *m) {
