    for (int i = 0; i < MAP_CAPACITY; i++) {
        m->entries[i].key = NULL;
        m->entries[i].count = 0;
    }
}

void map_put(Map *m, const char *key, int value) {
    for (int i = 0; i < m->size; i++) {
        if (strcmp(m->entries[i].key, key) == 0) {
            m->entries[i].count = value;
            return;
        }
    }
    if (m->size < MAP_CAPACITY) {
        m->entries[m->size].key = strdup(key);
        m->entries[m->size].count = value;
        m->size++;
    }
}

int map_get(Map *m, const char *key) {
