#include <stdio.h>
#include <string.h>

/* Simple hash map implementation for string keys */
#define MAX_ENTRIES 1024
#define HASH_SIZE 256

typedef struct {
    const char *key;
    int value;
} MapEntry;

static MapEntry hash_table[HASH_SIZE];
static int hash_table_used = 0;

static unsigned int hash_string(const char *s) {
    unsigned int h = 0;
    while (*s) {
        h = h * 31 + (unsigned char)*s;
        s++;
    }
    return h % HASH_SIZE;
}

/* Initialize the hash table */
static void map_init(void) {
    for (int i = 0; i < HASH_SIZE; i++) {
        hash_table[i].key = NULL;
        hash_table[i].value = 0;
    }
    hash_table_used = 0;
}

/* Get or create a map entry for the given key, returning pointer to value */
static int *map_get_or_create(const char *key) {
    unsigned int idx = hash_string(key);
    /* Check existing entries in this bucket */
    for (int i = 0; i < hash_table_used; i++) {
        if (hash_table[i].key != NULL && strcmp(hash_table[i].key, key) == 0) {
            return &hash_table[i].value;
        }
    }
    /* Not found, add new entry */
    if (hash_table_used < MAX_ENTRIES) {
        hash_table[hash_table_used].key = key;
        hash_table[hash_table_used].value = 0;
        hash_table_used++;
        return &hash_table[hash_table_used - 1].value;
    }
    return NULL;
}

int main(void) {
    const char *words[] = {"ant", "bee", "bee", "cat", "cat", "dog", "dog", "ant"};
    int n = 8;

    map_init();

    for (int i = 0; i < n; i++) {
        int *count = map_get_or_create(words[i]);
        if (count) {
            (*count)++;
        }
    }

    /* Print in fixed order: ant, bee, cat, dog */
    const char *order[] = {"ant", "bee", "cat", "dog"};
    for (int i = 0; i < 4; i++) {
        int *count = map_get_or_create(order[i]);
        printf("%s %d\n", order[i], count ? *count : 0);
    }

    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Simple map implementation for string keys */

typedef struct {
    char *key;
    int value;
} MapEntry;

typedef struct {
    MapEntry *entries;
    int size;
    int capacity;
} Map;

Map* map_create() {
    Map *m = (Map*)malloc(sizeof(Map));
    m->entries = NULL;
    m->size = 0;
    m->capacity = 0;
    return m;
}

void map_destroy(Map *m) {
    if (m) {
        for (int i = 0; i < m->size; i++) {
            free(m->entries[i].key);
        }
        free(m->entries);
        free(m);
    }
}

void map_put(Map *m, const char *key, int value) {
    for (int i = 0; i < m->size; i++) {
        if (strcmp(m->entries[i].key, key) == 0) {
            m->entries[i].value = value;
            return;
        }
    }
    if (m->size == m->capacity) {
        int new_capacity = m->capacity == 0 ? 4 : m->capacity * 2;
        m->entries = (MapEntry*)realloc(m->entries, new_capacity * sizeof(MapEntry));
        m->capacity = new_capacity;
    }
    m->entries[m->size].key = strdup(key);
    m->entries[m->size].value = value;
    m->size++;
}

int map_get(Map *m, const char *key) {
    for (int i = 0; i < m->size; i++) {
        if (strcmp(m->entries[i].key, key) == 0) {
            return m->entries[i].value;
        }
    }
    return 0;
}

int map_contains(Map *m, const char *key) {
    for (int i = 0; i < m->size; i++) {
        if (strcmp(m->entries[i].key, key) == 0) {
            return 1;
        }
    }
    return 0;
}

void map_incr(Map *m, const char *key) {
    int val = map_get(m, key);
    map_put(m, key, val + 1);
}

int main() {
    const char *words[] = {"ant", "bee", "bee", "cat", "cat", "dog", "dog", "ant"};
    int n = 8;

    Map *m = map_create();

    for (int i = 0; i < n; i++) {
        map_incr(m, words[i]);
    }

    const char *order[] = {"ant", "bee", "cat", "dog"};
    for (int i = 0; i < 4; i++) {
        printf("%s %d\n", order[i], map_get(m, order[i]));
    }

    map_destroy(m);
    return 0;
}

