/* Simple hash map for string keys */
typedef struct {
    char *key;
    int count;
} Entry;

typedef struct {
    Entry *entries;
    int size;
    int capacity;
} Map;

Map *map_new(int capacity) {
    Map *m = (Map *)malloc(sizeof(Map));
    if (!m) return NULL;
    m->capacity = capacity;
    m->size = 0;
    m->entries = (Entry *)calloc(capacity, sizeof(Entry));
    if (!m->entries) {
        free(m);
        return NULL;
    }
    return m;
}

void map_free(Map *m) {
    if (!m) return;
    for (int i = 0; i < m->size; i++) {
        free(m->entries[i].key);
    }
    free(m->entries);
    free(m);
}

/* Find entry by key, return index or -1 */
int map_find(Map *m, const char *key) {
    for (int i = 0; i < m->size; i++) {
        if (strcmp(m->entries[i].key, key) == 0) {
            return i;
        }
    }
    return -1;
}

/* Insert or increment key */
void map_insert_or_increment(Map *m, const char *key) {
    int idx = map_find(m, key);
    if (idx != -1) {
        m->entries[idx].count++;
        return;
    }
    if (m->size >= m->capacity) {
        /* Resize: double capacity */
        int newcap = m->capacity * 2;
        Entry *newentries = (Entry *)calloc(newcap, sizeof(Entry));
        if (!newentries) return;
        memcpy(newentries, m->entries, m->size * sizeof(Entry));
        free(m->entries);
        m->entries = newentries;
        m->capacity = newcap;
    }
    m->entries[m->size].key = strdup(key);
    m->entries[m->size].count = 1;
    m->size++;
}

int main(void) {
    const char *words[] = {"ant", "bee", "bee", "cat", "cat", "dog", "dog", "ant"};
    int n = 8;

    Map *m = map_new(4);
    for (int i = 0; i < n; i++) {
        map_insert_or_increment(m, words[i]);
    }

    /* Print in fixed order: ant, bee, cat, dog */
    const char *order[] = {"ant", "bee", "cat", "dog"};
    for (int i = 0; i < 4; i++) {
        int idx = map_find(m, order[i]);
        int count = (idx != -1) ? m->entries[idx].count : 0;
        printf("%s %d\n", order[i], count);
    }

    map_free(m);
    return 0;
}

