/* Simulate lib/io.aic interface */
typedef struct {
    FILE *f;
} AICFile;

/* Write a fixed string to a file, return 0 on success, -1 on error */
int aic_write_file(const char *filename, const char *data, size_t len) {
    FILE *f = fopen(filename, "wb");
    if (!f) return -1;
    size_t written = fwrite(data, 1, len, f);
    fclose(f);
    return (written == len) ? 0 : -1;
}

/* Read a file into a buffer, return the number of bytes read, or -1 on error */
ssize_t aic_read_file(const char *filename, char *buf, size_t buf_size, size_t *out_size) {
    FILE *f = fopen(filename, "rb");
    if (!f) return -1;
    /* First, get the file size */
    fseek(f, 0, SEEK_END);
    long size = ftell(f);
    fseek(f, 0, SEEK_SET);
    if (size < 0) {
        fclose(f);
        return -1;
    }
    if ((size_t)size > buf_size) {
        fclose(f);
        return -1;
    }
    size_t bytes_read = fread(buf, 1, (size_t)size, f);
    fclose(f);
    if (bytes_read != (size_t)size) return -1;
    *out_size = bytes_read;
    return (ssize_t)bytes_read;
}

