#include <sys/stat.h>

int main(void) {
    const char *filename = "bench_in.txt";
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) {
        perror("fopen");
        return 1;
    }

    // Determine the size of the file
    struct stat st;
    if (fstat(fileno(fp), &st) != 0) {
        perror("fstat");
        fclose(fp);
        return 1;
    }

    size_t size = (size_t)st.st_size;

    // Allocate a buffer of exactly that size
    unsigned char *buffer = (unsigned char *)malloc(size);
    if (buffer == NULL && size > 0) {
        perror("malloc");
        fclose(fp);
        return 1;
    }

    // Read the file into the buffer
    if (size > 0) {
        size_t bytesRead = fread(buffer, 1, size, fp);
        if (bytesRead != size) {
            fprintf(stderr, "Failed to read entire file\n");
            free(buffer);
            fclose(fp);
            return 1;
        }
    }

    // Print the size on its own line
    printf("%zu\n", size);

    free(buffer);
    fclose(fp);
    return 0;
}

#include <stdio.h>
#include <stdlib.h>
#include <sys/stat.h>

int main(void) {
    const char *filename = "bench_in.txt";

    /* Open the file to determine its size */
    FILE *fp = fopen(filename, "rb");
    if (fp == NULL) {
        perror("fopen");
        return 1;
    }

    /* Determine the size of the file */
    if (fseek(fp, 0, SEEK_END) != 0) {
        perror("fseek");
        fclose(fp);
        return 1;
    }

    long size = ftell(fp);
    if (size < 0) {
        perror("ftell");
        fclose(fp);
        return 1;
    }

    /* Rewind the file */
    if (fseek(fp, 0, SEEK_SET) != 0) {
        perror("fseek");
        fclose(fp);
        return 1;
    }

    /* Allocate a buffer of exactly that size */
    char *buffer = (char *)malloc(size);
    if (buffer == NULL && size > 0) {
        perror("malloc");
        fclose(fp);
        return 1;
    }

    /* Read the file into the buffer */
    if (size > 0) {
        size_t bytes_read = fread(buffer, 1, size, fp);
        if (bytes_read != (size_t)size) {
            perror("fread");
            free(buffer);
            fclose(fp);
            return 1;
        }
    }

    fclose(fp);

    /* Print the size on its own line */
    printf("%ld\n", size);

    /* Free the allocated buffer */
    free(buffer);

    return 0;
}

